{"command":"cd /workspace && cat > src/ig/matcher.rs <<'EOF'
//! Regular expression matcher used by the search engine.
//!
//! The pattern is parsed and translated with `regex-syntax`, adjusted for line
//! oriented searching and compiled with `regex-automata`.

use regex_automata::meta::Regex;
use regex_automata::Input;
use regex_syntax::ast::{self, Ast};
use regex_syntax::hir::{self, Hir, HirKind, Look};

#[derive(Clone, Debug)]
pub struct Error {
    kind: ErrorKind,
}

#[derive(Clone, Debug)]
#[allow(dead_code)]
pub enum ErrorKind {
    Regex(String),
    NotAllowed(String),
    InvalidLineTerminator(u8),
}

impl Error {
    fn regex<E: std::fmt::Display>(err: E) -> Error {
        Error {
            kind: ErrorKind::Regex(err.to_string()),
        }
    }
}

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self.kind {
            ErrorKind::Regex(ref s) => write!(f, "{}", s),
            ErrorKind::NotAllowed(ref lit) => {
                write!(f, "the literal {:?} is not allowed in a regex", lit)
            }
            ErrorKind::InvalidLineTerminator(byte) => {
                write!(f, "line terminators must be ASCII, but {:?} is not", byte)
            }
        }
    }
}

#[derive(Clone, Debug, Default)]
pub struct MatcherConfig {
    pub case_insensitive: bool,
    pub case_smart: bool,
    pub multi_line: bool,
    pub word: bool,
    pub fixed_strings: bool,
    pub line_terminator: Option<u8>,
}

#[derive(Clone, Debug)]
pub struct RegexMatcher {
    regex: Regex,
    line_terminator: Option<u8>,
    /// Bytes that can never be part of a match.
    non_matching: [bool; 256],
}

#[derive(Default)]
struct AstAnalysis {
    any_uppercase: bool,
    any_literal: bool,
}

impl AstAnalysis {
    fn from_ast(ast: &Ast) -> AstAnalysis {
        let mut a = AstAnalysis::default();
        a.visit(ast);
        a
    }

    fn done(&self) -> bool {
        self.any_uppercase && self.any_literal
    }

    fn visit(&mut self, ast: &Ast) {
        if self.done() {
            return;
        }
        match ast {
            Ast::Empty(_)
            | Ast::Flags(_)
            | Ast::Dot(_)
            | Ast::Assertion(_)
            | Ast::ClassUnicode(_)
            | Ast::ClassPerl(_) => {}
            Ast::Literal(x) => self.literal(x),
            Ast::ClassBracketed(x) => self.class_set(&x.kind),
            Ast::Repetition(x) => self.visit(&x.ast),
            Ast::Group(x) => self.visit(&x.ast),
            Ast::Alternation(alt) => {
                for x in &alt.asts {
                    self.visit(x);
                }
            }
            Ast::Concat(c) => {
                for x in &c.asts {
                    self.visit(x);
                }
            }
        }
    }

    fn class_set(&mut self, set: &ast::ClassSet) {
        if self.done() {
            return;
        }
        match set {
            ast::ClassSet::Item(item) => self.class_set_item(item),
            ast::ClassSet::BinaryOp(op) => {
                self.class_set(&op.lhs);
                self.class_set(&op.rhs);
            }
        }
    }

    fn class_set_item(&mut self, item: &ast::ClassSetItem) {
        if self.done() {
            return;
        }
        match item {
            ast::ClassSetItem::Empty(_)
            | ast::ClassSetItem::Ascii(_)
            | ast::ClassSetItem::Unicode(_)
            | ast::ClassSetItem::Perl(_) => {}
            ast::ClassSetItem::Literal(x) => self.literal(x),
            ast::ClassSetItem::Range(x) => {
                self.literal(&x.start);
                self.literal(&x.end);
            }
            ast::ClassSetItem::Bracketed(x) => self.class_set(&x.kind),
            ast::ClassSetItem::Union(u) => {
                for x in &u.items {
                    self.class_set_item(x);
                }
            }
        }
    }

    fn literal(&mut self, lit: &ast::Literal) {
        self.any_literal = true;
