            .utf8_empty(false)
            .nfa_size_limit(Some(100 * (1 << 20)))
            .onepass_size_limit(Some(10 * (1 << 20)))
            .dfa_size_limit(Some(1 << 20))
            .dfa_state_limit(Some(1_000))
            .hybrid_cache_capacity(1000 * (1 << 20));
        let regex = Regex::builder()
            .configure(meta)
            .build_from_hir(&hir)
            .map_err(Error::regex)?;
