        self.regex.is_match(Input::new(haystack))
    }

    /// Find the leftmost-first match starting the search at `at`.
    pub fn find_at(&self, haystack: &[u8], at: usize) -> Option<(usize, usize)> {
        let input = Input::new(haystack).span(at..haystack.len());
        self.regex.search(&input).map(|m| (m.start(), m.end()))
    }

    pub fn find(&self, haystack: &[u8]) -> Option<(usize, usize)> {
        self.find_at(haystack, 0)
    }

    /// Iterate over all successive non-overlapping matches.
    pub fn find_iter(&self, haystack: &[u8]) -> Vec<(usize, usize)> {
        let mut out = vec![];
        let mut last_end = 0;
        let mut last_match: Option<usize> = None;
        loop {
            if last_end > haystack.len() {
