//! Line oriented searching of a single file.

use std::fs::File;
use std::io::{self, Read};
use std::path::Path;

use super::matcher::RegexMatcher;

const DEFAULT_BUFFER_CAPACITY: usize = 64 * (1 << 10);

/// A block of matched lines (always complete lines, including terminators).
pub struct SinkMatch<'a> {
    pub bytes: &'a [u8],
    pub line_number: u64,
}

/// Reader performing BOM sniffing. Without a BOM the bytes are passed through
/// unchanged. UTF-16 input is transcoded to UTF-8.
struct BomReader {
    file: File,
    pending: Vec<u8>,
    pending_pos: usize,
    passthru: bool,
}

fn read_full(file: &mut File, buf: &mut [u8]) -> io::Result<usize> {
    let mut n = 0;
    while n < buf.len() {
        match file.read(&mut buf[n..]) {
            Ok(0) => break,
            Ok(k) => n += k,
            Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(e),
        }
    }
    Ok(n)
}

fn decode_utf16(bytes: &[u8], little_endian: bool) -> Vec<u8> {
    let units = bytes.chunks(2).map(|c| {
        if c.len() == 2 {
            if little_endian {
                u16::from_le_bytes([c[0], c[1]])
            } else {
                u16::from_be_bytes([c[0], c[1]])
            }
        } else {
            0xFFFD
        }
    });
    let s: String = char::decode_utf16(units)
        .map(|r| r.unwrap_or('\u{FFFD}'))
        .collect();
    s.into_bytes()
}

impl BomReader {
    fn new(mut file: File) -> io::Result<BomReader> {
        let mut peek = [0u8; 3];
        let n = read_full(&mut file, &mut peek)?;
        let peek = &peek[..n];
        if n >= 3 && peek == [0xEF, 0xBB, 0xBF] {
            return Ok(BomReader {
                file,
                pending: vec![],
                pending_pos: 0,
                passthru: true,
            });
        }
        if n >= 2 && (peek[..2] == [0xFF, 0xFE] || peek[..2] == [0xFE, 0xFF]) {
            let le = peek[..2] == [0xFF, 0xFE];
            let mut rest = peek[2..].to_vec();
            file.read_to_end(&mut rest)?;
            let decoded = decode_utf16(&rest, le);
            return Ok(BomReader {
                file,
                pending: decoded,
                pending_pos: 0,
                passthru: false,
            });
        }
        Ok(BomReader {
            file,
            pending: peek.to_vec(),
            pending_pos: 0,
            passthru: true,
        })
    }
}

impl Read for BomReader {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if self.pending_pos < self.pending.len() {
            let rest = &self.pending[self.pending_pos..];
            let len = std::cmp::min(buf.len(), rest.len());
            buf[..len].copy_from_slice(&rest[..len]);
            self.pending_pos += len;
            return Ok(len);
        }
        if !self.passthru {
            return Ok(0);
        }
        loop {
            match self.file.read(buf) {
                Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
                r => return r,
            }
        }
    }
}

struct LineBuffer {
    buf: Vec<u8>,
    pos: usize,
    last_lineterm: usize,
    end: usize,
    binary: bool,
}

impl LineBuffer {
    fn new() -> LineBuffer {
        LineBuffer {
            buf: vec![0; DEFAULT_BUFFER_CAPACITY],
            pos: 0,
            last_lineterm: 0,
            end: 0,
            binary: false,
        }
    }

    fn buffer(&self) -> &[u8] {
        &self.buf[self.pos..self.last_lineterm]
    }

    fn consume_all(&mut self) {
        self.pos = self.last_lineterm;
    }

    fn roll(&mut self) {
        let roll_start = self.last_lineterm;
        let roll_len = self.end - roll_start;
        self.buf.copy_within(roll_start..self.end, 0);
        self.pos = 0;
        self.last_lineterm = roll_len;
        self.end = roll_len;
    }

    fn ensure_capacity(&mut self) {
        if self.end < self.buf.len() {
            return;
        }
        let len = std::cmp::max(1, self.buf.len());
        let newlen = self.buf.len() + len * 2;
        self.buf.resize(newlen, 0);
    }

    fn fill<R: Read>(&mut self, rdr: &mut R) -> io::Result<bool> {
        if self.binary {
            return Ok(!self.buffer().is_empty());
        }
        self.roll();
        loop {
            self.ensure_capacity();
            let readlen = loop {
                match rdr.read(&mut self.buf[self.end..]) {
                    Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
                    r => break r?,
                }
            };
            if readlen == 0 {
                self.last_lineterm = self.end;
                return Ok(!self.buffer().is_empty());
            }
            let oldend = self.end;
            self.end += readlen;
            let newbytes = &self.buf[oldend..self.end];
            if let Some(i) = memchr::memchr(0, newbytes) {
                self.end = oldend + i;
                self.last_lineterm = self.end;
                self.binary = true;
                return Ok(self.pos < self.end);
            }
            if let Some(i) = memchr::memrchr(b'\n', newbytes) {
                self.last_lineterm = oldend + i + 1;
                return Ok(true);
            }
        }
    }
}

fn without_terminator(line: &[u8]) -> &[u8] {
    if let Some(&b'\n') = line.last() {
        &line[..line.len() - 1]
    } else {
        line
    }
}

/// Expand a match range to the complete lines containing it.
fn locate(bytes: &[u8], start: usize, end: usize) -> (usize, usize) {
    let line_start = memchr::memrchr(b'\n', &bytes[..start]).map_or(0, |i| i + 1);
    let line_end = if end > line_start && bytes[end - 1] == b'\n' {
        end
    } else {
        memchr::memchr(b'\n', &bytes[end..]).map_or(bytes.len(), |i| end + i + 1)
    };
    (line_start, line_end)
}

/// Search the file at `path`. The sink is called for every matched block of
/// lines and the search stops as soon as the sink returns `false`.
pub fn search_path<F>(matcher: &RegexMatcher, multi_line: bool, path: &Path, mut sink: F) -> io::Result<()>
where
    F: FnMut(&SinkMatch) -> bool,
{
    let file = File::open(path)?;
    let mut rdr = BomReader::new(file)?;
    if multi_line && !matcher.never_matches(b'\n') {
        let mut slice = vec![];
        rdr.read_to_end(&mut slice)?;
        search_multi_line(matcher, &slice, &mut sink);
        Ok(())
    } else {
        search_by_line(matcher, &mut rdr, &mut sink)
    }
}

fn search_by_line<R: Read, F>(matcher: &RegexMatcher, rdr: &mut R, sink: &mut F) -> io::Result<()>
where
    F: FnMut(&SinkMatch) -> bool,
{
    let mut lb = LineBuffer::new();
    let mut line_number: u64 = 1;
    loop {
        lb.consume_all();
        let didread = lb.fill(rdr)?;
        if !didread || lb.binary {
            return Ok(());
        }
        let buf = lb.buffer();
        let mut pos = 0;
        while pos < buf.len() {
            let end = memchr::memchr(b'\n', &buf[pos..]).map_or(buf.len(), |i| pos + i + 1);
            let line = &buf[pos..end];
            if matcher.is_match(without_terminator(line)) {
                let m = SinkMatch {
                    bytes: line,
                    line_number,
                };
                if !sink(&m) {
                    return Ok(());
                }
            }
            line_number += 1;
            pos = end;
        }
    }
}

fn count_lines(bytes: &[u8]) -> u64 {
    memchr::memchr_iter(b'\n', bytes).count() as u64
}

fn search_multi_line<F>(matcher: &RegexMatcher, slice: &[u8], sink: &mut F)
where
    F: FnMut(&SinkMatch) -> bool,
{
    let binary_upto = std::cmp::min(slice.len(), DEFAULT_BUFFER_CAPACITY);
    if memchr::memchr(0, &slice[..binary_upto]).is_some() {
        return;
    }
    let mut pos = 0;
    let mut last_match: Option<(usize, usize)> = None;
    // line counting state
    let mut counted_upto = 0;
    let mut line_number: u64 = 1;
    let mut emit = |range: (usize, usize), counted_upto: &mut usize, line_number: &mut u64| -> bool {
        if range.0 == range.1 {
            return false;
        }
        let bytes = &slice[range.0..range.1];
        if memchr::memchr(0, bytes).is_some() {
            return false;
        }
        *line_number += count_lines(&slice[*counted_upto..range.0]);
        *counted_upto = range.0;
        let m = SinkMatch {
            bytes,
            line_number: *line_number,
        };
        sink(&m)
    };
    while pos < slice.len() {
        let (s, e) = match matcher.find(&slice[pos..]) {
            None => {
                pos = slice.len();
                break;
            }
            Some((s, e)) => (s + pos, e + pos),
        };
        pos = e;
        if s == e && pos < slice.len() {
            pos += 1;
        }
        let line = locate(slice, s, e);
        match last_match.take() {
            None => last_match = Some(line),
            Some(last) => {
                if last.1 >= line.0 {
                    last_match = Some((last.0, line.1));
                } else {
                    last_match = Some(line);
                    if !emit(last, &mut counted_upto, &mut line_number) {
                        return;
                    }
                }
            }
        }
    }
    let _ = pos;
    if let Some(last) = last_match {
        emit(last, &mut counted_upto, &mut line_number);
    }
}
