/// Reader performing BOM sniffing. Without a BOM the bytes are passed through
/// unchanged. UTF-16 input is transcoded to UTF-8.
struct BomReader {
    file: File,
    pending: Vec<u8>,
    pending_pos: usize,
    passthru: bool,
}

fn read_full(file: &mut File, buf: &mut [u8]) -> io::Result<usize> {
    let mut n = 0;
    while n < buf.len() {
        match file.read(&mut buf[n..]) {
            Ok(0) => break,
            Ok(k) => n += k,
            Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(e),
        }
    }
    Ok(n)
}

fn decode_utf16(bytes: &[u8], little_endian: bool) -> Vec<u8> {
    let units = bytes.chunks(2).map(|c| {
        if c.len() == 2 {
            if little_endian {
                u16::from_le_bytes([c[0], c[1]])
            } else {
                u16::from_be_bytes([c[0], c[1]])
            }
        } else {
            0xFFFD
        }
    });
    let s: String = char::decode_utf16(units)
        .map(|r| r.unwrap_or('\u{FFFD}'))
        .collect();
    s.into_bytes()
}

impl BomReader {
    fn new(mut file: File) -> io::Result<BomReader> {
        let mut peek = [0u8; 3];
        let n = read_full(&mut file, &mut peek)?;
        let peek = &peek[..n];
        if n >= 3 && peek == [0xEF, 0xBB, 0xBF] {
            return Ok(BomReader {
                file,
                pending: vec![],
                pending_pos: 0,
                passthru: true,
            });
        }
        if n >= 2 && (peek[..2] == [0xFF, 0xFE] || peek[..2] == [0xFE, 0xFF]) {
            let le = peek[..2] == [0xFF, 0xFE];
            let mut rest = peek[2..].to_vec();
            file.read_to_end(&mut rest)?;
            let decoded = decode_utf16(&rest, le);
            return Ok(BomReader {
                file,
                pending: decoded,
                pending_pos: 0,
                passthru: false,
            });
        }
        Ok(BomReader {
            file,
            pending: peek.to_vec(),
            pending_pos: 0,
            passthru: true,
        })
    }
}

impl Read for BomReader {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if self.pending_pos < self.pending.len() {
            let rest = &self.pending[self.pending_pos..];
            let len = std::cmp::min(buf.len(), rest.len());
            buf[..len].copy_from_slice(&rest[..len]);
