use std::path::PathBuf;

use anyhow::Result;
use ignore::overrides::{Override, OverrideBuilder};
use ignore::types::{Types, TypesBuilder};

use crate::args::SortKey;
use crate::file_types::FILE_TYPES;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SortBy {
    pub key: SortKey,
    pub reverse: bool,
}

#[derive(Clone)]
pub struct SearchConfig {
    pub pattern: String,
    pub paths: Vec<PathBuf>,
    pub case_insensitive: bool,
    pub case_smart: bool,
    pub overrides: Override,
    pub types: Types,
    pub search_hidden: bool,
    pub follow_links: bool,
    pub word_regexp: bool,
    pub fixed_strings: bool,
    pub multi_line: bool,
    pub sort_by: Option<SortBy>,
}

pub fn types_builder() -> TypesBuilder {
    let mut builder = TypesBuilder::new();
    for (name, globs) in FILE_TYPES {
        for glob in globs.iter() {
            builder
                .add(name, glob)
                .expect("built-in file type definitions are valid");
        }
    }
    builder
}

impl SearchConfig {
    pub fn from(pattern: String, paths: Vec<PathBuf>) -> Result<SearchConfig> {
        let mut builder = TypesBuilder::new();
        builder.add_defaults();
        let types = builder.build()?;
        let overrides = OverrideBuilder::new(std::env::current_dir()?).build()?;
        Ok(SearchConfig {
            pattern,
            paths,
            case_insensitive: false,
            case_smart: false,
            overrides,
            types,
            search_hidden: false,
            follow_links: false,
            word_regexp: false,
            fixed_strings: false,
            multi_line: false,
            sort_by: None,
        })
    }

    pub fn globs(mut self, globs: &[String]) -> Result<SearchConfig> {
        let mut builder = OverrideBuilder::new(std::env::current_dir()?);
        for glob in globs {
            builder.add(glob)?;
        }
        self.overrides = builder.build()?;
        Ok(self)
    }

    pub fn file_types(mut self, type_matching: &[String], type_not: &[String]) -> Result<SearchConfig> {
        let mut builder = types_builder();
        for t in type_matching {
            builder.select(t);
        }
        for t in type_not {
            builder.negate(t);
        }
        self.types = builder.build()?;
        Ok(self)
    }
}
