use std::fs;
use std::io;
use std::path::Path;
use std::sync::mpsc;
use std::time::SystemTime;

use ignore::{DirEntry, WalkBuilder, WalkState};

use super::file_entry::{FileEntry, LineMatch};
use super::matcher::{MatcherConfig, RegexMatcher};
use super::search::{search_path, SinkMatch};
use super::search_config::{SearchConfig, SortBy};
use crate::args::SortKey;

pub enum Event {
    NewEntry(FileEntry),
    SearchingFinished,
