/// Spawn the background search. Results are reported through `tx`.
pub fn search(config: SearchConfig, tx: mpsc::Sender<Event>) {
    std::thread::spawn(move || {
        let searcher = Searcher::new(config, tx);
        searcher.run();
    });
}

struct Searcher {
    config: SearchConfig,
    tx: mpsc::Sender<Event>,
}

impl Searcher {
    fn new(config: SearchConfig, tx: mpsc::Sender<Event>) -> Self {
        Self { config, tx }
    }

    fn matcher_config(&self) -> MatcherConfig {
        MatcherConfig {
            case_insensitive: self.config.case_insensitive,
            case_smart: self.config.case_smart,
            multi_line: self.config.multi_line,
            word: self.config.word_regexp,
            fixed_strings: self.config.fixed_strings,
            line_terminator: if self.config.multi_line {
                None
            } else {
                Some(b'\n')
            },
        }
    }

    fn run(self) {
        let matcher_config = self.matcher_config();
        // The matcher is built inside of the search thread, an invalid
        // pattern terminates the search.
        let matcher = RegexMatcher::new(&matcher_config, &self.config.pattern)
        .expect("Cannot build RegexMatcher");

        let builder = self.walk_builder();
        let multi_line = self.config.multi_line;
        if self.config.sort_by.is_some() {
            for entry in builder.build().flatten() {
                if let Some(file_entry) = search_entry(&matcher, multi_line, &entry) {
                    if self.tx.send(Event::NewEntry(file_entry)).is_err() {
                        return;
                    }
                }
            }
        } else {
            builder.build_parallel().run(|| {
                let tx = self.tx.clone();
                let matcher = matcher.clone();
                Box::new(move |result| {
                    let entry = match result {
                        Ok(entry) => entry,
                        Err(_) => return WalkState::Continue,
                    };
                    if let Some(file_entry) = search_entry(&matcher, multi_line, &entry) {
                        if tx.send(Event::NewEntry(file_entry)).is_err() {
                            return WalkState::Quit;
                        }
                    }
                    WalkState::Continue
                })
            });
        }
        let _ = self.tx.send(Event::SearchingFinished);
    }

    fn walk_builder(&self) -> WalkBuilder {
        let paths = &self.config.paths;
        let mut builder = WalkBuilder::new(&paths[0]);
        for path in &paths[1..] {
            builder.add(path);
        }
        builder
            .hidden(!self.config.search_hidden)
            .follow_links(self.config.follow_links)
            .overrides(self.config.overrides.clone())
            .types(self.config.types.clone());
        if let Some(sort_by) = self.config.sort_by {
            configure_sort(&mut builder, sort_by);
        }
        builder
    }
}

fn configure_sort(builder: &mut WalkBuilder, sort_by: SortBy) {
    let reverse = sort_by.reverse;
    match sort_by.key {
        SortKey::Path => {
            if reverse {
                builder.sort_by_file_name(|a, b| a.cmp(b).reverse());
            } else {
                builder.sort_by_file_name(|a, b| a.cmp(b));
            }
        }
        SortKey::Modified => {
            builder.sort_by_file_path(move |a, b| sort_by_metadata_time(a, b, reverse, |md| md.modified()));
        }
        SortKey::Accessed => {
            builder.sort_by_file_path(move |a, b| sort_by_metadata_time(a, b, reverse, |md| md.accessed()));
        }
        SortKey::Created => {
            builder.sort_by_file_path(move |a, b| sort_by_metadata_time(a, b, reverse, |md| md.created()));
        }
    }
}

fn sort_by_metadata_time<G>(p1: &Path, p2: &Path, reverse: bool, get_time: G) -> Ordering
where
    G: Fn(&fs::Metadata) -> io::Result<SystemTime>,
{
    let t1 = match p1.metadata().and_then(|md| get_time(&md)) {
        Ok(t) => t,
        Err(_) => return Ordering::Greater,
    };
    let t2 = match p2.metadata().and_then(|md| get_time(&md)) {
        Ok(t) => t,
        Err(_) => return Ordering::Less,
    };
    if reverse {
        t1.cmp(&t2).reverse()
    } else {
        t1.cmp(&t2)
    }
}

fn display_name(path: &Path) -> String {
    let stripped = path.strip_prefix("./").unwrap_or(path);
    stripped.to_string_lossy().into_owned()
}

fn search_entry(matcher: &RegexMatcher, multi_line: bool, entry: &DirEntry) -> Option<FileEntry> {
    if !entry.file_type().is_some_and(|ft| ft.is_file()) {
        return None;
    }
    let path = entry.path();
    let mut matches: Vec<LineMatch> = vec![];
    let _ = search_path(matcher, multi_line, path, |m: &SinkMatch| {
        let text = match std::str::from_utf8(m.bytes) {
            Ok(text) => text,
            Err(_) => return false,
        };
        collect_matches(matcher, text, m.line_number, &mut matches);
        true
    });
    if matches.is_empty() {
        return None;
    }
    Some(FileEntry {
        name: display_name(path),
        path: path.to_string_lossy().into_owned(),
        matches,
    })
}

fn split_lines(text: &str) -> Vec<(usize, &str)> {
    let mut lines = vec![];
    let mut start = 0;
    let bytes = text.as_bytes();
    while start < bytes.len() {
        let end = memchr::memchr(b'\n', &bytes[start..]).map_or(bytes.len(), |i| start + i);
        lines.push((start, &text[start..end]));
        start = end + 1;
    }
    lines
}

fn collect_matches(matcher: &RegexMatcher, text: &str, line_number: u64, out: &mut Vec<LineMatch>) {
    let found = matcher.find_iter(text.as_bytes());
    let lines = split_lines(text);
    if lines.len() <= 1 {
        let line = lines.first().map(|(_, l)| *l).unwrap_or("");
        let len = line.len();
        let offsets = found
            .iter()
            .filter_map(|&(s, e)| {
                let e = e.min(len);
                if s < e {
                    Some((s, e))
                } else {
                    None
                }
            })
            .collect();
        out.push(LineMatch {
            line_number,
            text: line.to_string(),
            offsets,
        });
        return;
    }
    let merged = match (found.first(), found.last()) {
        (Some(first), Some(last)) => Some((first.0, last.1)),
        _ => None,
    };
    for (i, (start, line)) in lines.iter().enumerate() {
        let mut offsets = vec![];
        if let Some((ms, me)) = merged {
            let ls = *start;
            let le = start + line.len();
            let s = ms.max(ls);
            let e = me.min(le);
            if s < e {
                offsets.push((s - ls, e - ls));
            }
        }
        out.push(LineMatch {
            line_number: line_number + i as u64,
            text: line.to_string(),
            offsets,
        });
    }
}
