use ratatui::{
    layout::Rect,
    style::Style,
    text::{Line, Span},
    widgets::{Block, BorderType, List, ListItem, ListState},
    Frame,
};

use crate::ig::file_entry::{FileEntry, LineMatch};
use crate::ui::theme::Theme;

pub enum Item {
    Header { name: String, path: String },
    Match(LineMatch),
}

impl Item {
    fn is_header(&self) -> bool {
        matches!(self, Item::Header { .. })
    }
}

#[derive(Default)]
pub struct ResultList {
    items: Vec<Item>,
    state: ListState,
    file_entries_count: usize,
    matches_count: usize,
    filtered_matches_count: usize,
}

impl ResultList {
    pub fn add_entry(&mut self, entry: FileEntry) {
        self.file_entries_count += 1;
        self.matches_count += entry.matches.len();
        self.items.push(Item::Header {
            name: entry.name,
            path: entry.path,
        });
        for m in entry.matches {
            self.items.push(Item::Match(m));
        }
        if self.state.selected().is_none() {
            self.state.select(Some(1));
        }
    }

    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }

    pub fn get_selected_entry(&self) -> Option<(String, u64)> {
        let index = self.state.selected()?;
        let line_number = match self.items.get(index)? {
            Item::Match(m) => m.line_number,
            Item::Header { .. } => return None,
        };
        let path = self.items[..index].iter().rev().find_map(|item| match item {
            Item::Header { path, .. } => Some(path.clone()),
            _ => None,
        })?;
        Some((path, line_number))
    }

    fn select_previous_rule(&mut self, index: usize) {
        self.state.select(Some(index));
        if index <= self.state.offset() {
            *self.state.offset_mut() = index.saturating_sub(1);
        }
    }

    pub fn next_match(&mut self) {
        if self.is_empty() {
            return;
        }
        let index = match self.state.selected() {
            Some(i) => {
                if i == self.items.len() - 1 {
                    i
                } else if self.items[i + 1].is_header() {
                    i + 2
                } else {
                    i + 1
                }
            }
            None => 1,
        };
        self.state.select(Some(index));
    }

    pub fn previous_match(&mut self) {
        if self.is_empty() {
            return;
        }
        let index = match self.state.selected() {
            Some(i) => {
                if i <= 1 {
                    1
                } else if self.items[i - 1].is_header() {
                    i - 2
                } else {
                    i - 1
                }
            }
            None => 1,
        };
        self.select_previous_rule(index);
    }

    pub fn next_file(&mut self) {
        if self.is_empty() {
            return;
        }
        let current = self.state.selected().unwrap_or(0);
        let next_header = self.items[current + 1..]
            .iter()
            .position(|item| item.is_header())
            .map(|p| p + current + 1);
        if let Some(h) = next_header {
            self.state.select(Some(h + 1));
        }
    }

    fn current_header_index(&self) -> Option<usize> {
        let current = self.state.selected()?;
        self.items[..=current.min(self.items.len().saturating_sub(1))]
            .iter()
            .rposition(|item| item.is_header())
    }

    pub fn previous_file(&mut self) {
        if self.is_empty() {
            return;
        }
        let current_header = match self.current_header_index() {
            Some(h) => h,
            None => return,
        };
        let index = if current_header == 0 {
            1
        } else {
            let previous_header = self.items[..current_header]
                .iter()
                .rposition(|item| item.is_header())
                .unwrap_or(0);
            previous_header + 1
        };
        self.select_previous_rule(index);
    }

    pub fn top(&mut self) {
        if self.is_empty() {
            return;
        }
        self.select_previous_rule(1);
    }

    pub fn bottom(&mut self) {
        if self.is_empty() {
            return;
        }
        self.state.select(Some(self.items.len() - 1));
