        }
        self.items.remove(index);
        self.filtered_matches_count += 1;
        let new_index = if index < self.items.len() && !self.items[index].is_header() {
            index
        } else {
            index - 1
        };
        self.state.select(Some(new_index));
    }

    pub fn remove_current_file(&mut self) {
