            x: area.x + (area.width - width) / 2,
            y: area.y + (area.height - height) / 2,
            width,
            height,
        };
        let visible_width = width.saturating_sub(4);
        let visible_height = height.saturating_sub(4);
        self.max_x = self.content_width.saturating_sub(visible_width);
        self.max_y = content_height.saturating_sub(visible_height);
        self.scroll_x = self.scroll_x.min(self.max_x);
        self.scroll_y = self.scroll_y.min(self.max_y);

        let block = Block::default()
            .borders(Borders::ALL)
            .title(" igrep 1.3.0 ")
            .title_alignment(Alignment::Center)
            .border_style(Style::default().fg(theme.popup_border_color()));
        let inner = block.inner(popup_area);
        let text_area = Rect {
            x: inner.x.saturating_add(1),
            y: inner.y.saturating_add(1),
            width: inner.width.saturating_sub(2),
            height: inner.height.saturating_sub(2),
        };
        let lines: Vec<Line> = self.content.iter().map(|l| Line::from(l.clone())).collect();
        let paragraph = Paragraph::new(lines).scroll((self.scroll_y, self.scroll_x));
        frame.render_widget(Clear, popup_area);
        frame.render_widget(block, popup_area);
        frame.render_widget(paragraph, text_area);
    }
}
