use ratatui::{
    layout::{Alignment, Constraint, Direction, Layout, Position, Rect},
    style::{Modifier, Style},
    widgets::{Block, Borders, Clear, Paragraph},
    Frame,
};

use crate::ui::theme::Theme;

#[derive(Default)]
pub struct SearchPopup {
    visible: bool,
    pattern: String,
    edited_pattern: String,
    cursor_position: usize,
}

impl SearchPopup {
    pub fn toggle(&mut self) {
        self.visible = !self.visible;
        if self.visible {
            self.edited_pattern = self.pattern.clone();
            self.cursor_position = self.edited_pattern.chars().count();
        }
    }

    pub fn is_visible(&self) -> bool {
        self.visible
    }

    // Characters are inserted at the cursor position.
    pub fn insert_char(&mut self, c: char) {
        self.edited_pattern.insert(self.cursor_position, c);
        self.move_cursor_right();
    }

    pub fn remove_char(&mut self) {
        if self.edited_pattern.is_empty() {
            return;
        }
        let index = self.cursor_position.saturating_sub(1);
        self.edited_pattern.remove(index);
        self.move_cursor_left();
    }

    pub fn delete_char(&mut self) {
        if self.cursor_position < self.edited_pattern.chars().count() {
            self.edited_pattern.remove(self.cursor_position);
        }
    }

    pub fn move_cursor_left(&mut self) {
