#[derive(Clone, Debug)]
pub enum EditorCommand {
    Builtin(Editor),
    Custom(String, String),
}

impl EditorCommand {
    pub fn new(custom_command: Option<String>, editor: Option<String>) -> Result<Self> {
        if let Some(custom_command) = custom_command {
            return Self::parse_custom_command(&custom_command);
        }
        if let Some(editor) = editor {
            let editor = Editor::from_str(&editor).map_err(|e| anyhow!(e))?;
            return Ok(EditorCommand::Builtin(editor));
        }
        Ok(EditorCommand::Builtin(Self::read_from_env()?))
    }

    fn parse_custom_command(custom_command: &str) -> Result<Self> {
        let check = || -> Result<(String, String)> {
            let (program, args) = custom_command
                .split_once(' ')
                .ok_or_else(|| anyhow!("Expected program and its arguments"))?;
            if args.matches("{file_name}").count() != 1 {
                return Err(anyhow!("Expected one occurrence of '{{file_name}}'."));
            }
            if args.matches("{line_number}").count() != 1 {
                return Err(anyhow!("Expected one occurrence of '{{line_number}}'."));
            }
            Ok((program.to_string(), args.to_string()))
        };
        let (program, args) =
            check().with_context(|| format!("Incorrect editor command: '{custom_command}'"))?;
        Ok(EditorCommand::Custom(program, args))
    }

    fn read_from_env() -> Result<Editor> {
        for var in ["IGREP_EDITOR", "VISUAL", "EDITOR"] {
            if let Ok(value) = std::env::var(var) {
                let name = value.rsplit('/').next().unwrap_or("");
                return Editor::from_str(name).map_err(|e| anyhow!(e)).with_context(|| {
                    format!(
