                        value,
                        var,
                        EDITORS.join(", ")
                    )
                });
            }
        }
        Ok(Editor::Vim)
    }

    pub fn program(&self) -> String {
        match self {
            EditorCommand::Builtin(editor) => editor.program().to_string(),
            EditorCommand::Custom(program, _) => program.clone(),
        }
    }

    pub fn args(&self, file_name: &str, line_number: u64) -> Vec<String> {
        match self {
            EditorCommand::Builtin(editor) => editor.args(file_name, line_number),
            EditorCommand::Custom(_, args) => args
                .split_whitespace()
                .map(|arg| {
                    arg.replace("{file_name}", file_name)
                        .replace("{line_number}", &line_number.to_string())
                })
                .collect(),
        }
    }

    pub fn spawn(&self, file_name: &str, line_number: u64) -> Result<Child, String> {
        let program = self.program();
        Command::new(&program)
            .args(self.args(file_name, line_number))
            .spawn()
            .map_err(|_| format!("Failed to open editor '{program}'. Is it installed?"))
    }
}
