use std::io::{self, Stdout};
use std::sync::mpsc::{self, Receiver, TryRecvError};
use std::time::Duration;

use anyhow::Result;
use crossterm::{
    event::{self, Event, KeyCode, KeyEvent, KeyEventKind, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::CrosstermBackend,
    layout::{Constraint, Direction, Layout},
    Frame, Terminal,
};

use crate::args::{ContextViewerPosition, SortKey, ThemeKind};
use crate::editor::EditorCommand;
use crate::ig::search_config::{SearchConfig, SortBy};
use crate::ig::searcher::{self, Event as SearcherEvent};
use crate::ui::bottom_bar::{self, AppState};
use crate::ui::context_viewer::ContextViewer;
use crate::ui::keymap_popup::KeymapPopup;
use crate::ui::result_list::ResultList;
use crate::ui::search_popup::SearchPopup;
use crate::ui::theme::Theme;

type Term = Terminal<CrosstermBackend<Stdout>>;

#[derive(PartialEq, Eq)]
enum State {
    Idle,
    Searching,
    Error(String),
}

pub struct App {
    search_config: SearchConfig,
    editor_command: EditorCommand,
    result_list: ResultList,
    context_viewer: ContextViewer,
    search_popup: SearchPopup,
    keymap_popup: KeymapPopup,
    theme: Theme,
    state: State,
    rx: Option<Receiver<SearcherEvent>>,
    input_buffer: String,
    input_display: String,
    exit: bool,
    open_file: bool,
}

fn setup_terminal() -> Result<Term> {
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    Ok(Terminal::new(backend)?)
}

fn restore_terminal(terminal: &mut Term) -> Result<()> {
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;
    Ok(())
}

impl App {
    pub fn new(
        search_config: SearchConfig,
        editor_command: EditorCommand,
        context_viewer_position: ContextViewerPosition,
        theme: ThemeKind,
    ) -> Self {
        let mut search_popup = SearchPopup::default();
        search_popup.set_pattern(search_config.pattern.clone());
        Self {
            search_config,
            editor_command,
            result_list: ResultList::default(),
            context_viewer: ContextViewer::new(context_viewer_position),
            search_popup,
            keymap_popup: KeymapPopup::new(),
            theme: Theme::new(theme),
            state: State::Idle,
            rx: None,
            input_buffer: String::new(),
            input_display: String::new(),
            exit: false,
            open_file: false,
        }
    }

    pub fn run(&mut self) -> Result<()> {
        self.search();
        let mut terminal = setup_terminal()?;
        loop {
            terminal.draw(|f| self.draw(f))?;
            self.handle_searcher_events();
            if self.exit {
                break;
            }
            if event::poll(Duration::from_millis(30))? {
                let event = event::read()?;
                self.handle_event(event);
            }
            if self.exit {
                break;
            }
            if self.open_file {
                self.open_file = false;
                self.open_selected_file();
                terminal = setup_terminal()?;
            }
        }
        restore_terminal(&mut terminal)?;
        Ok(())
    }

    fn search(&mut self) {
        if self.state != State::Idle {
            return;
        }
        self.result_list = ResultList::default();
        let (tx, rx) = mpsc::channel();
        self.rx = Some(rx);
        self.state = State::Searching;
        searcher::search(self.search_config.clone(), tx);
    }

    fn handle_searcher_events(&mut self) {
        let rx = match &self.rx {
            Some(rx) => rx,
            None => return,
        };
        loop {
            match rx.try_recv() {
                Ok(SearcherEvent::NewEntry(entry)) => self.result_list.add_entry(entry),
                Ok(SearcherEvent::SearchingFinished) => {
                    if self.state == State::Searching {
                        self.state = State::Idle;
                    }
                }
                Err(TryRecvError::Empty) => break,
                Err(TryRecvError::Disconnected) => {
                    if self.state == State::Searching {
                        self.exit = true;
                    }
                    self.rx = None;
                    break;
                }
            }
        }
    }

    fn open_selected_file(&mut self) {
        let (path, line_number) = match self.result_list.get_selected_entry() {
            Some(entry) => entry,
            None => return,
        };
        match self.editor_command.spawn(&path, line_number) {
            Ok(mut child) => {
                let _ = child.wait();
            }
            Err(message) => self.state = State::Error(message),
        }
    }

    fn sort(&mut self, key: SortKey) {
        let sort_by = match self.search_config.sort_by {
            Some(SortBy { key: k, reverse: false }) if k == key => SortBy { key, reverse: true },
            _ => SortBy { key, reverse: false },
        };
        self.search_config.sort_by = Some(sort_by);
        self.search();
    }

    fn handle_event(&mut self, event: Event) {
        if let Event::Key(key) = event {
            if key.kind != KeyEventKind::Press {
                return;
            }
            if self.keymap_popup.is_visible() {
                self.handle_keymap_popup_key(key);
            } else if self.search_popup.is_visible() {
                self.handle_search_popup_key(key);
            } else {
                self.handle_main_key(key);
            }
        }
    }

    fn handle_keymap_popup_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Down | KeyCode::Char('j') => self.keymap_popup.go_down(),
            KeyCode::Up | KeyCode::Char('k') => self.keymap_popup.go_up(),
            KeyCode::Right | KeyCode::Char('l') => self.keymap_popup.go_right(),
            KeyCode::Left | KeyCode::Char('h') => self.keymap_popup.go_left(),
            _ => self.keymap_popup.toggle(),
        }
    }

    fn handle_search_popup_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.search_popup.cancel()
            }
            KeyCode::Char(c) => {
                if !key.modifiers.intersects(KeyModifiers::CONTROL | KeyModifiers::ALT) {
                    self.search_popup.insert_char(c);
                }
            }
            KeyCode::Backspace => self.search_popup.remove_char(),
            KeyCode::Delete => self.search_popup.delete_char(),
            KeyCode::Left => self.search_popup.move_cursor_left(),
            KeyCode::Right => self.search_popup.move_cursor_right(),
            KeyCode::Esc | KeyCode::F(5) => self.search_popup.cancel(),
            KeyCode::Enter => {
                let pattern = self.search_popup.accept();
                self.search_config.pattern = pattern;
                self.search();
            }
            _ => {}
        }
    }

    fn handle_main_key(&mut self, key: KeyEvent) {
        if key.code == KeyCode::Char('c') && key.modifiers.contains(KeyModifiers::CONTROL) {
            self.exit = true;
            return;
        }
        self.input_display.clear();
        match key.code {
            KeyCode::Char(c) => self.handle_char(c),
            KeyCode::Esc => {
                if self.input_buffer.is_empty() {
                    self.exit = true;
                } else {
                    self.input_buffer.clear();
                }
            }
            code => {
                self.input_buffer.clear();
                match code {
                    KeyCode::Down => self.result_list.next_match(),
                    KeyCode::Up => self.result_list.previous_match(),
                    KeyCode::Right | KeyCode::PageDown => self.result_list.next_file(),
                    KeyCode::Left | KeyCode::PageUp => self.result_list.previous_file(),
                    KeyCode::Home => self.result_list.top(),
                    KeyCode::End => self.result_list.bottom(),
                    KeyCode::Delete => self.result_list.remove_current_entry(),
                    KeyCode::Enter => self.open_file = true,
                    KeyCode::F(1) => self.keymap_popup.toggle(),
                    KeyCode::F(5) => self.search_popup.toggle(),
                    _ => {}
                }
            }
        }
    }

    fn handle_char(&mut self, c: char) {
        self.input_buffer.push(c);
        let buffer = self.input_buffer.clone();
        match buffer.as_str() {
            "g" | "d" => {
                self.input_display = format!("{}…", buffer);
                return;
            }
            _ => {}
        }
        self.input_buffer.clear();
        match buffer.as_str() {
            "q" => self.exit = true,
            "j" => self.result_list.next_match(),
            "k" => self.result_list.previous_match(),
            "l" => self.result_list.next_file(),
            "h" => self.result_list.previous_file(),
            "gg" => self.result_list.top(),
            "G" => self.result_list.bottom(),
            "dd" => self.result_list.remove_current_entry(),
            "dw" => self.result_list.remove_current_file(),
            "v" => self.context_viewer.toggle_vertical(),
            "s" => self.context_viewer.toggle_horizontal(),
            "+" => self.context_viewer.increase_size(),
            "-" => self.context_viewer.decrease_size(),
            "/" => self.search_popup.toggle(),
            "?" => self.keymap_popup.toggle(),
            "n" => self.sort(SortKey::Path),
            "m" => self.sort(SortKey::Modified),
            "c" => self.sort(SortKey::Created),
            "a" => self.sort(SortKey::Accessed),
            _ => self.input_display = buffer,
        }
    }

    fn draw(&mut self, frame: &mut Frame) {
        let chunks = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Min(1), Constraint::Length(1)])
            .split(frame.area());
        let (list_area, viewer_area) = self.context_viewer.split(chunks[0]);
        self.result_list.draw(frame, list_area, &self.theme);
        if let Some(viewer_area) = viewer_area {
            let selected = self.result_list.get_selected_entry();
            self.context_viewer.draw(frame, viewer_area, selected, &self.theme);
        }
        let state = match &self.state {
            State::Idle => AppState::Finished,
            State::Searching => AppState::Searching,
            State::Error(e) => AppState::Error(e),
        };
        bottom_bar::draw(frame, chunks[1], &self.result_list, state, &self.input_display, &self.theme);
        self.keymap_popup.draw(frame, &self.theme);
        self.search_popup.draw(frame, &self.theme);
    }
}
