mod args;
mod editor;
mod file_types;
mod ig;
mod ui;

use std::io::Write;
use std::path::PathBuf;

use anyhow::Result;

use crate::editor::EditorCommand;
use crate::ig::search_config::{SearchConfig, SortBy};
use crate::ui::app::App;

fn print_type_list() -> Result<()> {
    let builder = ig::search_config::types_builder();
    let mut stdout = std::io::stdout().lock();
    for def in builder.definitions() {
        writeln!(stdout, "{}: {}", def.name(), def.globs().join(", "))?;
    }
    Ok(())
}

fn main() -> Result<()> {
    let args = args::parse();

    if args.type_list {
        return print_type_list();
    }

    let pattern = args.pattern.unwrap_or_default();
    let paths = if args.paths.is_empty() {
        vec![PathBuf::from("./")]
    } else {
        args.paths
    };
    let sort_by = match (args.sort_by_reverse, args.sort_by) {
        (Some(key), _) => Some(SortBy { key, reverse: true }),
        (None, Some(key)) => Some(SortBy { key, reverse: false }),
        (None, None) => None,
    };

    let mut search_config = SearchConfig::from(pattern, paths)?
        .globs(&args.globs)?
        .file_types(&args.type_matching, &args.type_not)?;
    search_config.case_insensitive = args.ignore_case;
    search_config.case_smart = args.smart_case;
    search_config.search_hidden = args.search_hidden;
    search_config.follow_links = args.follow_links;
    search_config.word_regexp = args.word_regexp;
    search_config.fixed_strings = args.fixed_strings;
    search_config.multi_line = args.multiline;
    search_config.sort_by = sort_by;

    let editor_command = EditorCommand::new(args.custom_command, args.editor)?;

    let mut app = App::new(search_config, editor_command, args.context_viewer, args.theme);
    app.run()
}
