use ratatui::{
    buffer::Buffer,
    layout::Rect,
    style::Style,
    text::Line,
    widgets::Widget,
};
use unicode_width::UnicodeWidthStr;

/// Remove control characters which are not rendered by the terminal.
pub fn strip_control(s: &str) -> String {
    s.chars().filter(|c| !c.is_control()).collect()
}

/// A title rendered centered on the top border of a block. When the title
/// doesn't fit, it is truncated on the right side.
pub struct CenteredTitle<'a> {
    pub title: &'a str,
}

impl Widget for CenteredTitle<'_> {
    fn render(self, area: Rect, buf: &mut Buffer) {
        if area.width < 2 || area.height == 0 {
            return;
        }
        let available = area.width - 2;
        let title_width = self.title.width() as u16;
        let offset = if title_width <= available {
            (available - title_width) / 2
        } else {
            0
        };
        let title_area = Rect {
            x: area.x + 1 + offset,
            y: area.y,
            width: available - offset,
            height: 1,
        };
        Line::from(self.title).style(Style::default()).render(title_area, buf);
    }
}
