//! Small helpers shared by the language specific highlighters.

/// Highlight classes, mapped to theme colors.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Class {
    Plain,
    Comment,
    String,
    Number,
    Keyword,
    Function,
    Support,
    Variable,
    Type,
    Escape,
    Embedded,
    Invalid,
}

/// A line being highlighted.
pub struct Scanner<'a> {
    pub chars: Vec<char>,
    pub pos: usize,
    pub out: Vec<(Class, String)>,
    _line: &'a str,
}

impl<'a> Scanner<'a> {
    pub fn new(line: &'a str) -> Self {
        Self {
            chars: line.chars().collect(),
            pos: 0,
            out: vec![],
            _line: line,
        }
    }

    pub fn eof(&self) -> bool {
        self.pos >= self.chars.len()
    }

    pub fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    pub fn peek_at(&self, offset: usize) -> Option<char> {
        self.chars.get(self.pos + offset).copied()
    }

    pub fn prev(&self) -> Option<char> {
        if self.pos == 0 {
            None
        } else {
            self.chars.get(self.pos - 1).copied()
        }
    }

    pub fn starts_with(&self, s: &str) -> bool {
        let mut i = self.pos;
        for c in s.chars() {
            if self.chars.get(i) != Some(&c) {
                return false;
            }
            i += 1;
        }
        true
    }

    pub fn rest(&self) -> String {
        self.chars[self.pos..].iter().collect()
    }

    /// Emit `n` characters with the given class.
    pub fn emit(&mut self, n: usize, class: Class) {
        let end = std::cmp::min(self.pos + n, self.chars.len());
        if end <= self.pos {
            return;
        }
        let text: String = self.chars[self.pos..end].iter().collect();
        self.push(class, &text);
        self.pos = end;
    }

    pub fn push(&mut self, class: Class, text: &str) {
        if text.is_empty() {
            return;
        }
        if let Some(last) = self.out.last_mut() {
            if last.0 == class {
                last.1.push_str(text);
                return;
            }
        }
        self.out.push((class, text.to_string()));
    }

    /// Emit the remaining characters of the line.
    pub fn emit_rest(&mut self, class: Class) {
        let n = self.chars.len() - self.pos;
        self.emit(n, class);
    }

    /// Length of the identifier starting at the current position.
    pub fn ident_len(&self) -> usize {
        let mut i = self.pos;
        while i < self.chars.len() && is_ident_char(self.chars[i]) {
            i += 1;
        }
        i - self.pos
    }

    pub fn word_at(&self, start: usize, len: usize) -> String {
        self.chars[start..start + len].iter().collect()
    }

    /// Next non whitespace character at or after `pos`.
    pub fn next_non_ws(&self, from: usize) -> Option<(usize, char)> {
        let mut i = from;
        while i < self.chars.len() {
            if !self.chars[i].is_whitespace() {
                return Some((i, self.chars[i]));
            }
            i += 1;
        }
        None
    }

    /// Previous non whitespace character before `pos`.
    pub fn prev_non_ws(&self, before: usize) -> Option<(usize, char)> {
        let mut i = before;
        while i > 0 {
            i -= 1;
            if !self.chars[i].is_whitespace() {
                return Some((i, self.chars[i]));
            }
        }
        None
    }
}

pub fn is_ident_start(c: char) -> bool {
    c == '_' || c.is_alphabetic()
}

pub fn is_ident_char(c: char) -> bool {
    c == '_' || c.is_alphanumeric()
}
