//! Syntax highlighting of files displayed in the context viewer.

mod rust;
mod scanner;

use ratatui::style::{Color, Style};

use crate::args::ThemeKind;
use crate::ui::widgets::strip_control;
use scanner::Class;

pub fn foreground(theme: ThemeKind) -> Color {
    match theme {
        ThemeKind::Dark => Color::Rgb(192, 197, 206),
        ThemeKind::Light => Color::Rgb(79, 91, 102),
    }
}

fn color(class: Class, theme: ThemeKind) -> Color {
    match class {
        Class::Plain => foreground(theme),
        Class::Comment => match theme {
            ThemeKind::Dark => Color::Rgb(101, 115, 126),
            ThemeKind::Light => Color::Rgb(167, 173, 186),
        },
        Class::String => Color::Rgb(163, 190, 140),
        Class::Number => Color::Rgb(208, 135, 112),
        Class::Keyword => Color::Rgb(180, 142, 173),
        Class::Function => Color::Rgb(143, 161, 179),
        Class::Support | Class::Escape => Color::Rgb(150, 181, 180),
        Class::Variable => Color::Rgb(191, 97, 106),
        Class::Type => Color::Rgb(235, 203, 139),
        Class::Embedded => Color::Rgb(171, 121, 103),
        Class::Invalid => match theme {
            ThemeKind::Dark => Color::Rgb(43, 48, 59),
            ThemeKind::Light => Color::Rgb(239, 241, 245),
        },
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Language {
    Plain,
    Rust,
}

fn detect_language(path: &str) -> Language {
    let file_name = path.rsplit('/').next().unwrap_or(path);
    let extension = file_name.rsplit_once('.').map(|(_, e)| e).unwrap_or("");
    match extension {
        "rs" => Language::Rust,
        _ => Language::Plain,
    }
}

/// Split the content into lines and highlight every line.
pub fn highlight(path: &str, content: &str, theme: ThemeKind) -> Vec<Vec<(Style, String)>> {
    let lines = split_lines(content);
    let language = detect_language(path);
    let classified: Vec<Vec<(Class, String)>> = match language {
        Language::Plain => lines
            .iter()
            .map(|l| vec![(Class::Plain, l.to_string())])
            .collect(),
        Language::Rust => {
            let mut h = rust::RustHighlighter::default();
            lines.iter().map(|l| h.highlight_line(l)).collect()
        }
    };
    classified
        .into_iter()
        .map(|spans| {
            spans
                .into_iter()
                .map(|(class, text)| {
                    (
                        Style::default().fg(color(class, theme)),
                        strip_control(&text.replace('\t', "    ")),
                    )
                })
                .filter(|(_, text)| !text.is_empty())
                .collect()
        })
        .collect()
}

fn split_lines(content: &str) -> Vec<&str> {
    let mut lines: Vec<&str> = content.split('\n').collect();
    if content.ends_with('\n') {
        lines.pop();
    }
    lines
}
