//! Highlighting of Rust source files.

use super::scanner::{is_ident_char, is_ident_start, Class, Scanner};

const KEYWORDS: &[&str] = &[
    "break", "const", "continue", "crate", "else", "enum", "extern", "fn", "for", "if", "let",
    "loop", "match", "mod", "move", "mut", "pub", "ref", "return", "static", "struct", "super",
    "trait", "type", "unsafe", "use", "where", "while", "Self",
];

const TYPES: &[&str] = &[
    "bool", "char", "str", "i8", "i16", "i32", "i64", "i128", "isize", "u8", "u16", "u32", "u64",
    "u128", "usize", "f32", "f64",
];

const RESERVED: &[&str] = &[
    "abstract", "become", "do", "final", "macro", "override", "priv", "typeof", "unsized",
    "virtual", "yield",
];

const NUMBER_SUFFIXES: &[&str] = &[
    "u8", "u16", "u32", "u64", "u128", "usize", "i8", "i16", "i32", "i64", "i128", "isize", "f32",
    "f64",
];

const FORMAT_MACROS: &[&str] = &["format", "print", "println", "write", "writeln"];

#[derive(Clone, Copy, PartialEq, Eq)]
enum StrKind {
    Normal { format: bool },
    Raw { hashes: usize },
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ParamState {
    Pattern,
    Type,
}

#[derive(Default)]
pub struct RustHighlighter {
    comment_depth: usize,
    string: Option<StrKind>,
    /// The next identifier is a function name.
    expect_fn_name: bool,
    /// Waiting for the opening parenthesis of a function parameter list.
    expect_params: bool,
    /// Parenthesis depth inside of the parameter list of a function.
    params_depth: usize,
    param_state: Option<ParamState>,
    /// Waiting for the body of a struct definition.
    expect_struct_body: bool,
    struct_depth: usize,
    /// Parenthesis depth of a format macro invocation.
    format_depth: usize,
    expect_format_paren: bool,
    paren_depth: usize,
    /// Inside of closure parameters.
    closure_params: Option<ParamState>,
    /// Waiting for an attribute name.
    expect_attribute: bool,
    macro_rules: bool,
}

impl RustHighlighter {
    pub fn highlight_line(&mut self, line: &str) -> Vec<(Class, String)> {
        let mut s = Scanner::new(line);
        while !s.eof() {
            if self.comment_depth > 0 {
                self.block_comment(&mut s);
                continue;
            }
            if let Some(kind) = self.string {
                self.string_body(&mut s, kind);
                continue;
            }
            self.token(&mut s);
        }
        s.out
    }

    fn block_comment(&mut self, s: &mut Scanner) {
        while !s.eof() {
            if s.starts_with("*/") {
                s.emit(2, Class::Comment);
                self.comment_depth -= 1;
                if self.comment_depth == 0 {
                    return;
                }
            } else if s.starts_with("/*") {
                s.emit(2, Class::Comment);
                self.comment_depth += 1;
            } else {
                s.emit(1, Class::Comment);
            }
        }
    }

    fn escape_len(s: &Scanner) -> usize {
        if s.peek() != Some('\\') {
            return 0;
        }
        match s.peek_at(1) {
            Some('n') | Some('r') | Some('t') | Some('0') | Some('\\') | Some('\'') | Some('"') => 2,
            Some('x') => {
                let a = s.peek_at(2).is_some_and(|c| c.is_ascii_hexdigit());
                let b = s.peek_at(3).is_some_and(|c| c.is_ascii_hexdigit());
                if a && b {
                    4
                } else {
                    0
                }
            }
            Some('u') => {
                if s.peek_at(2) != Some('{') {
                    return 0;
                }
                let mut i = 3;
                while s.peek_at(i).is_some_and(|c| c.is_ascii_hexdigit() || c == '_') {
                    i += 1;
                }
                if i > 3 && s.peek_at(i) == Some('}') {
                    i + 1
                } else {
                    0
                }
            }
            _ => 0,
        }
    }

    fn string_body(&mut self, s: &mut Scanner, kind: StrKind) {
        while !s.eof() {
            match kind {
                StrKind::Raw { hashes } => {
                    if s.peek() == Some('"') {
                        let mut ok = true;
                        for i in 0..hashes {
                            if s.peek_at(1 + i) != Some('#') {
                                ok = false;
                                break;
                            }
                        }
                        if ok {
                            s.emit(1 + hashes, Class::Plain);
                            self.string = None;
                            return;
                        }
                    }
                    s.emit(1, Class::String);
                }
                StrKind::Normal { format } => {
                    if s.peek() == Some('"') {
                        s.emit(1, Class::Plain);
                        self.string = None;
                        return;
                    }
                    let n = Self::escape_len(s);
                    if n > 0 {
                        s.emit(n, Class::Escape);
                        continue;
                    }
                    if format && s.peek() == Some('{') {
                        if s.peek_at(1) == Some('{') {
                            s.emit(2, Class::String);
                            continue;
                        }
                        let mut i = 1;
                        let mut ok = false;
                        while let Some(c) = s.peek_at(i) {
                            if c == '}' {
                                ok = true;
                                break;
                            }
                            if c == '{' || c == '"' {
                                break;
                            }
                            i += 1;
                        }
                        if ok {
                            s.emit(i + 1, Class::Number);
                            continue;
                        }
                    }
                    s.emit(1, Class::String);
                }
            }
        }
    }

    fn number_len(s: &Scanner) -> (usize, usize) {
        // returns (number length, suffix length)
        let chars = &s.chars;
        let start = s.pos;
        let mut i = start;
        let n = chars.len();
        let is = |i: usize, f: &dyn Fn(char) -> bool| i < n && f(chars[i]);
        if chars[i] == '0' && is(i + 1, &|c| c == 'x') && is(i + 2, &|c| c.is_ascii_hexdigit() || c == '_') {
            i += 2;
            while is(i, &|c| c.is_ascii_hexdigit() || c == '_') {
                i += 1;
            }
        } else if chars[i] == '0' && is(i + 1, &|c| c == 'o') && is(i + 2, &|c| c.is_digit(8) || c == '_') {
            i += 2;
            while is(i, &|c| c.is_digit(8) || c == '_') {
                i += 1;
            }
        } else if chars[i] == '0' && is(i + 1, &|c| c == 'b') && is(i + 2, &|c| c == '0' || c == '1' || c == '_') {
            i += 2;
            while is(i, &|c| c == '0' || c == '1' || c == '_') {
                i += 1;
            }
        } else {
            while is(i, &|c| c.is_ascii_digit() || c == '_') {
                i += 1;
            }
            if is(i, &|c| c == '.') && is(i + 1, &|c| c.is_ascii_digit()) {
                i += 1;
                while is(i, &|c| c.is_ascii_digit() || c == '_') {
                    i += 1;
                }
                if is(i, &|c| c == 'e' || c == 'E') {
                    let mut j = i + 1;
                    if is(j, &|c| c == '+' || c == '-') {
                        j += 1;
                    }
                    if is(j, &|c| c.is_ascii_digit() || c == '_') {
                        while is(j, &|c| c.is_ascii_digit() || c == '_') {
                            j += 1;
                        }
                        i = j;
                    }
                }
            }
        }
        let num_len = i - start;
        // suffix
        let mut suffix = 0;
        for suf in NUMBER_SUFFIXES {
            let sl = suf.len();
            if i + sl <= n && chars[i..i + sl].iter().copied().eq(suf.chars()) {
                if i + sl == n || !is_ident_char(chars[i + sl]) {
                    suffix = sl;
                    break;
                }
            }
        }
        if suffix == 0 && i < n && is_ident_char(chars[i]) {
            return (0, 0);
        }
        (num_len, suffix)
    }

    fn token(&mut self, s: &mut Scanner) {
        let c = s.peek().unwrap();
        if c.is_whitespace() {
            s.emit(1, Class::Plain);
            return;
        }
        if s.starts_with("//") {
            s.emit_rest(Class::Comment);
            return;
        }
        if s.starts_with("/*") {
            s.emit(2, Class::Comment);
            self.comment_depth = 1;
            return;
        }
        // byte strings and raw strings
        if (c == 'b' || c == 'r') && (s.pos == 0 || !is_ident_char(s.prev().unwrap())) {
            let mut i = 0;
            let mut prefix = 0;
            if s.peek_at(i) == Some('b') {
                i += 1;
                prefix += 1;
            }
            let raw = s.peek_at(i) == Some('r');
            if raw {
                i += 1;
                prefix += 1;
            }
            let mut hashes = 0;
            if raw {
                while s.peek_at(i) == Some('#') {
                    i += 1;
                    hashes += 1;
                }
            }
            if prefix > 0 && s.peek_at(i) == Some('"') {
                s.emit(prefix, Class::Keyword);
                if raw {
                    s.emit(hashes, Class::Plain);
                    s.emit(1, Class::String);
                    self.string = Some(StrKind::Raw { hashes });
                } else {
                    s.emit(1, Class::Plain);
                    self.string = Some(StrKind::Normal { format: false });
                }
                return;
            }
            if c == 'b' && s.peek_at(1) == Some('\'') {
                s.emit(1, Class::Keyword);
                self.char_or_lifetime(s);
                return;
            }
        }
        if c == '"' {
            s.emit(1, Class::Plain);
            self.string = Some(StrKind::Normal {
                format: self.format_depth > 0,
            });
            return;
        }
        if c == '\'' {
            self.char_or_lifetime(s);
            return;
        }
        if c.is_ascii_digit() && (s.pos == 0 || !is_ident_char(s.prev().unwrap())) {
            let (n, suffix) = Self::number_len(s);
            if n > 0 {
                s.emit(n, Class::Number);
                s.emit(suffix, Class::Keyword);
                return;
            }
            let len = s.ident_len();
            s.emit(len.max(1), Class::Plain);
            return;
        }
        if c == '$' && s.peek_at(1).is_some_and(is_ident_start) {
            let start = s.pos;
            s.pos += 1;
            let len = s.ident_len();
            s.pos = start;
            s.emit(len + 1, Class::Variable);
            // fragment specifier
            if s.peek() == Some(':') && s.peek_at(1).is_some_and(is_ident_start) {
                s.emit(1, Class::Plain);
                let len = s.ident_len();
                s.emit(len, Class::Keyword);
            }
            return;
        }
        if is_ident_start(c) {
            self.identifier(s);
            return;
        }
        if c == '#' && (s.starts_with("#[") || s.starts_with("#![")) {
            let n = if s.starts_with("#[") { 2 } else { 3 };
            s.emit(n, Class::Plain);
            self.expect_attribute = true;
            return;
        }
        self.punctuation(s, c);
    }

    fn char_or_lifetime(&mut self, s: &mut Scanner) {
        // s.peek() == '\''
        let start = s.pos;
        s.pos += 1;
        let esc = Self::escape_len(s);
        if esc > 0 && s.peek_at(esc) == Some('\'') {
            s.pos = start;
            s.emit(1, Class::Plain);
            s.emit(esc, Class::Escape);
            s.emit(1, Class::Plain);
            return;
        }
        if s.peek().is_some() && s.peek() != Some('\\') && s.peek_at(1) == Some('\'') {
            s.pos = start;
            s.emit(1, Class::Plain);
            s.emit(1, Class::String);
            s.emit(1, Class::Plain);
            return;
        }
        if s.peek().is_some_and(is_ident_start) {
            let len = s.ident_len();
            let after = s.pos + len;
            s.pos = start;
            if s.chars.get(after) == Some(&':') && s.chars.get(after + 1) != Some(&':') {
                s.emit(len + 1, Class::Plain);
            } else {
                s.emit(len + 1, Class::Keyword);
            }
            return;
        }
        s.pos = start;
        s.emit(1, Class::Plain);
    }

    fn punctuation(&mut self, s: &mut Scanner, c: char) {
        match c {
            '(' => {
                self.paren_depth += 1;
                if self.expect_format_paren {
                    self.expect_format_paren = false;
                    self.format_depth = self.paren_depth;
                }
                if self.expect_params {
                    self.expect_params = false;
                    self.params_depth = 1;
                    self.param_state = Some(ParamState::Pattern);
                } else if self.params_depth > 0 {
                    self.params_depth += 1;
                }
            }
            ')' => {
                if self.format_depth > 0 && self.paren_depth == self.format_depth {
                    self.format_depth = 0;
                }
                self.paren_depth = self.paren_depth.saturating_sub(1);
                if self.params_depth > 0 {
                    self.params_depth -= 1;
                    if self.params_depth == 0 {
                        self.param_state = None;
                    }
                }
            }
            ',' => {
                if self.params_depth == 1 {
                    self.param_state = Some(ParamState::Pattern);
                }
                if self.closure_params.is_some() {
                    self.closure_params = Some(ParamState::Pattern);
                }
            }
            ':' => {
                if s.peek_at(1) != Some(':') && (s.pos == 0 || s.prev() != Some(':')) {
                    if self.params_depth == 1 {
                        self.param_state = Some(ParamState::Type);
                    }
                    if self.closure_params.is_some() {
                        self.closure_params = Some(ParamState::Type);
                    }
                }
            }
            '|' => {
                if self.closure_params.is_some() {
                    self.closure_params = None;
                } else if s.peek_at(1) == Some('|') {
                    // `||` either an empty closure or a logical or
                } else {
                    let prev = s.prev_non_ws(s.pos).map(|(_, c)| c);
                    let starts_closure = match prev {
                        None => true,
                        Some(p) => matches!(p, '(' | ',' | '=' | '{' | ';' | '[') ,
                    } || self.previous_word_is(s, "move");
                    if starts_closure {
                        self.closure_params = Some(ParamState::Pattern);
                    }
                }
                if s.peek_at(1) == Some('|') && self.closure_params.is_none() {
                    s.emit(2, Class::Plain);
                    return;
                }
            }
            '{' => {
                if self.expect_struct_body {
                    self.expect_struct_body = false;
                    self.struct_depth = 1;
                } else if self.struct_depth > 0 {
                    self.struct_depth += 1;
                }
                self.expect_params = false;
            }
            '}' => {
                if self.struct_depth > 0 {
                    self.struct_depth -= 1;
                }
            }
            ';' => {
                self.expect_struct_body = false;
                self.expect_params = false;
            }
            _ => {}
        }
        s.emit(1, Class::Plain);
    }

    fn previous_word_is(&self, s: &Scanner, word: &str) -> bool {
        let mut i = s.pos;
        while i > 0 && s.chars[i - 1].is_whitespace() {
            i -= 1;
        }
        let end = i;
        while i > 0 && is_ident_char(s.chars[i - 1]) {
            i -= 1;
        }
        s.chars[i..end].iter().collect::<String>() == word
    }

    fn identifier(&mut self, s: &mut Scanner) {
        let start = s.pos;
        let len = s.ident_len();
        let word = s.word_at(start, len);
        let after = start + len;
        let next = s.chars.get(after).copied();
        let preceded_by_path = start >= 2 && s.chars[start - 1] == ':' && s.chars[start - 2] == ':';

        if self.expect_attribute {
            self.expect_attribute = false;
            s.emit(len, Class::Variable);
            return;
        }

        if self.expect_fn_name {
            self.expect_fn_name = false;
            if !KEYWORDS.contains(&word.as_str()) {
                s.emit(len, Class::Function);
                self.expect_params = true;
                return;
            }
        }

        // parameters of a function
        let in_pattern = (self.params_depth > 0 && self.param_state == Some(ParamState::Pattern))
            || self.closure_params == Some(ParamState::Pattern);
        if in_pattern {
            let class = match word.as_str() {
                "mut" | "ref" => Class::Keyword,
                _ => Class::Variable,
            };
            s.emit(len, class);
            return;
        }

        if word == "self" {
            s.emit(len, Class::Variable);
            return;
        }
        if word == "true" || word == "false" {
            s.emit(len, Class::Number);
            return;
        }
        if word == "macro_rules" && next == Some('!') {
            s.emit(len + 1, Class::Support);
            self.macro_rules = true;
            return;
        }
        if next == Some('!') && s.chars.get(after + 1) != Some(&'=') {
            if FORMAT_MACROS.contains(&word.as_str()) {
                self.expect_format_paren = true;
            }
            s.emit(len, Class::Plain);
            return;
        }
        if word == "impl" {
            let first = s.prev_non_ws(start).is_none() || self.previous_word_is(s, "unsafe") || self.previous_word_is(s, "pub");
            s.emit(len, if first { Class::Keyword } else { Class::Plain });
            return;
        }
        if KEYWORDS.contains(&word.as_str()) {
            match word.as_str() {
                "fn" => self.expect_fn_name = true,
                "struct" => self.expect_struct_body = true,
                _ => {}
            }
            if word == "let" {
                s.emit(len, Class::Keyword);
                self.let_binding(s);
                return;
            }
            s.emit(len, Class::Keyword);
            return;
        }
        if TYPES.contains(&word.as_str()) {
            s.emit(len, Class::Keyword);
            return;
        }
        if RESERVED.contains(&word.as_str()) {
            s.emit(len, Class::Invalid);
            return;
        }
        if self.struct_depth == 1 && self.next_is_single_colon(s, after) {
            s.emit(len, Class::Variable);
            return;
        }
        if len >= 2
            && word.chars().next().is_some_and(|c| c.is_ascii_uppercase())
            && word.chars().all(|c| c.is_ascii_uppercase() || c.is_ascii_digit() || c == '_')
        {
            s.emit(len, Class::Number);
            return;
        }
        if next == Some('(')
            && !preceded_by_path
            && word.chars().next().is_some_and(|c| c.is_lowercase() || c == '_')
        {
            s.emit(len, Class::Support);
            return;
        }
        s.emit(len, Class::Plain);
    }

    fn next_is_single_colon(&self, s: &Scanner, after: usize) -> bool {
        match s.next_non_ws(after) {
            Some((i, ':')) => s.chars.get(i + 1) != Some(&':'),
            _ => false,
        }
    }

    /// Handle `let [mut] name = |...|` closures.
    fn let_binding(&mut self, s: &mut Scanner) {
        let mut i = s.pos;
        let skip_ws = |i: &mut usize| {
            while *i < s.chars.len() && s.chars[*i].is_whitespace() {
                *i += 1;
            }
        };
        skip_ws(&mut i);
        let mut has_mut = false;
        if s.chars[i..].starts_with(&['m', 'u', 't']) && s.chars.get(i + 3).is_some_and(|c| c.is_whitespace()) {
            has_mut = true;
            i += 3;
            skip_ws(&mut i);
        }
        let name_start = i;
        while i < s.chars.len() && is_ident_char(s.chars[i]) {
            i += 1;
        }
        if i == name_start || !is_ident_start(s.chars[name_start]) {
            return;
        }
        let name_end = i;
        skip_ws(&mut i);
        if s.chars.get(i) != Some(&'=') || s.chars.get(i + 1) == Some(&'=') {
            return;
        }
        i += 1;
        skip_ws(&mut i);
        let is_closure = s.chars.get(i) == Some(&'|')
            || (s.chars[i..].starts_with(&['m', 'o', 'v', 'e']) && {
                let mut j = i + 4;
                skip_ws(&mut j);
                s.chars.get(j) == Some(&'|')
            });
        if !is_closure {
            return;
        }
        // emit up to the name
        let ws1 = name_start - s.pos;
        if has_mut {
            // whitespace, mut, whitespace
            let mut_pos = s.chars[s.pos..].iter().position(|&c| c == 'm').unwrap() + s.pos;
            s.emit(mut_pos - s.pos, Class::Plain);
            s.emit(3, Class::Keyword);
            s.emit(name_start - s.pos, Class::Plain);
        } else {
            s.emit(ws1, Class::Plain);
        }
        s.emit(name_end - name_start, Class::Function);
    }
}
