{"command":"cd /workspace && cat > src/ui/highlight/python.rs <<'EOF'
//! Highlighting of Python source files.

use super::scanner::{is_ident_char, is_ident_start, Class, Scanner};

const KEYWORDS: &[&str] = &[
    "as", "assert", "async", "await", "break", "class", "continue", "def", "del", "elif", "else",
    "except", "exec", "finally", "for", "from", "global", "if", "import", "lambda", "nonlocal",
    "pass", "raise", "return", "try", "while", "with", "yield",
];

const CONSTANTS: &[&str] = &["None", "True", "False", "Ellipsis", "NotImplemented", "__debug__"];

const BUILTIN_FUNCTIONS: &[&str] = &[
    "__import__", "abs", "all", "any", "ascii", "basestring", "bin", "callable", "chr",
    "classmethod", "cmp", "compile", "delattr", "dir", "divmod", "enumerate", "eval", "execfile",
    "file", "filter", "format", "getattr", "globals", "hasattr", "hash", "help", "hex", "id",
    "input", "intern", "isinstance", "issubclass", "iter", "len", "locals", "map", "max",
    "min", "next", "oct", "open", "ord", "pow", "print", "property", "range",
    "raw_input", "reduce", "reload", "repr", "reversed", "round", "setattr", "sorted",
    "staticmethod", "sum", "super", "type", "unichr", "vars", "xrange", "zip",
];

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
struct StrState {
    quote: char,
    triple: bool,
    raw: bool,
    format: bool,
    bytes: bool,
    docstring: bool,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Paren {
    Call,
    Group,
    Params,
    ClassBases,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum ClassState {
    /// After the `class` keyword, before the bases.
    Header,
    /// After the closing parenthesis of the bases.
    AfterBases,
}

#[derive(Default)]
pub struct PythonHighlighter {
    string: Option<StrState>,
    parens: Vec<(Paren, char)>,
    expect_def_name: bool,
    expect_params: bool,
    /// Inside of the parameters: true when the next identifier is a name.
    param_name: bool,
    lambda: bool,
    class: Option<ClassState>,
    class_name_done: bool,
    for_statement: bool,
    /// Brace depth inside of a f-string replacement field.
    fstring_expr: Vec<(StrState, usize)>,
}

fn is_constant(word: &str) -> bool {
    let trimmed = word.trim_start_matches('_');
    let caps = trimmed.chars().take_while(|c| c.is_ascii_uppercase()).count();
    caps >= 3 && trimmed.chars().all(|c| c.is_ascii_uppercase() || c == '_')
}

impl PythonHighlighter {
    pub fn highlight_line(&mut self, line: &str) -> Vec<(Class, String)> {
        let mut s = Scanner::new(line);
        let mut first_token = true;
        self.for_statement = false;
        while !s.eof() {
            if let Some(st) = self.string {
                self.string_body(&mut s, st);
                continue;
            }
            let c = s.peek().unwrap();
            if c.is_whitespace() {
                let class = self.whitespace_class();
                s.emit(1, class);
                continue;
            }
            self.token(&mut s, first_token);
            first_token = false;
        }
        if self.class == Some(ClassState::AfterBases) && self.parens.is_empty() {
            // the class header is complete after the colon, keep the state otherwise
        }
        s.out
    }

    fn whitespace_class(&self) -> Class {
        if let Some(state) = self.class {
            if state == ClassState::Header || self.in_class_bases() {
                return Class::Embedded;
            }
        }
        Class::Plain
    }

    fn in_class_bases(&self) -> bool {
        self.parens.iter().any(|(p, _)| *p == Paren::ClassBases)
    }

    fn top_paren(&self) -> Option<Paren> {
        self.parens.last().map(|(p, _)| *p)
    }

    fn escape_len(s: &Scanner) -> usize {
        if s.peek() != Some('\\') {
            return 0;
        }
        let c = match s.peek_at(1) {
            Some(c) => c,
            None => return 1,
        };
        match c {
            '\\' | '\'' | '"' | 'a' | 'b' | 'f' | 'n' | 'r' | 't' | 'v' | '\n' => 2,
            '0'..='7' => {
                let mut i = 2;
                while i < 4 && s.peek_at(i).is_some_and(|c| ('0'..='7').contains(&c)) {
                    i += 1;
                }
                i
            }
            'x' => {
                if s.peek_at(2).is_some_and(|c| c.is_ascii_hexdigit())
                    && s.peek_at(3).is_some_and(|c| c.is_ascii_hexdigit())
                {
                    4
                } else {
                    0
                }
            }
            'u' | 'U' => {
                let n = if c == 'u' { 4 } else { 8 };
                for i in 0..n {
                    if !s.peek_at(2 + i).is_some_and(|c| c.is_ascii_hexdigit()) {
                        return 0;
                    }
                }
                2 + n
            }
            'N' => {
                if s.peek_at(2) != Some('{') {
                    return 0;
                }
                let mut i = 3;
                while let Some(c) = s.peek_at(i) {
                    if c == '}' {
                        return i + 1;
                    }
                    i += 1;
                }
                0
            }
            _ => 0,
        }
    }

    fn string_end(s: &Scanner, st: &StrState) -> bool {
        if st.triple {
            s.peek() == Some(st.quote) && s.peek_at(1) == Some(st.quote) && s.peek_at(2) == Some(st.quote)
        } else {
            s.peek() == Some(st.quote)
        }
    }

    fn string_body(&mut self, s: &mut Scanner, st: StrState) {
        let content_class = if st.docstring { Class::Comment } else { Class::String };
        let delim_class = if st.docstring { Class::Comment } else { Class::Plain };
        while !s.eof() {
            if Self::string_end(s, &st) {
                s.emit(if st.triple { 3 } else { 1 }, delim_class);
                self.string = None;
                return;
            }
            if st.docstring {
                if s.peek() == Some('\\') && s.peek_at(1).is_some() {
                    s.emit(2, Class::Comment);
                } else {
                    s.emit(1, Class::Comment);
                }
                continue;
            }
            if st.format {
                if s.starts_with("{{") || s.starts_with("}}") {
                    s.emit(2, Class::Escape);
                    continue;
                }
                if s.peek() == Some('{') {
                    s.emit(1, Class::Plain);
                    self.fstring_body(s, st);
                    if self.string.is_none() {
                        return;
                    }
                    continue;
                }
            }
            if st.raw && !st.bytes && !st.format {
                if self.regex_token(s) {
                    continue;
                }
            } else {
                let n = Self::escape_len(s);
                if n > 0 && !st.raw {
                    s.emit(n, Class::Escape);
                    continue;
                }
                if !st.format {
                    if let Some(n) = Self::placeholder_len(s) {
                        if s.starts_with("%(") {
                            // %(name)s
                            let close = s.chars[s.pos..].iter().position(|&c| c == ')').unwrap();
                            s.emit(2, Class::Number);
                            s.emit(close - 2, Class::Variable);
                            s.emit(n - close, Class::Number);
                        } else {
                            s.emit(n, Class::Number);
                        }
                        continue;
                    }
                }
            }
            if !st.triple && s.peek() == Some('\\') && s.pos + 1 == s.chars.len() {
                s.emit(1, content_class);
                continue;
            }
            s.emit(1, content_class);
        }
        if !st.triple && !(s.chars.last() == Some(&'\\')) {
            // unterminated single quoted strings end with the line
            self.string = None;
        }
    }

    fn placeholder_len(s: &Scanner) -> Option<usize> {
        let c = s.peek()?;
        if c == '%' {
            if s.peek_at(1) == Some('%') {
                return Some(2);
            }
            let mut i = 1;
            if s.peek_at(i) == Some('(') {
                while let Some(c) = s.peek_at(i) {
                    i += 1;
                    if c == ')' {
                        break;
                    }
                }
            }
            while s.peek_at(i).is_some_and(|c| "#0- +".contains(c)) {
                i += 1;
            }
            while s.peek_at(i).is_some_and(|c| c.is_ascii_digit() || c == '*') {
                i += 1;
            }
            if s.peek_at(i) == Some('.') {
                i += 1;
                while s.peek_at(i).is_some_and(|c| c.is_ascii_digit() || c == '*') {
                    i += 1;
                }
            }
            while s.peek_at(i).is_some_and(|c| "hlL".contains(c)) {
                i += 1;
            }
            if s.peek_at(i).is_some_and(|c| "diouxXeEfFgGcrsa".contains(c)) {
                return Some(i + 1);
            }
            return None;
        }
        if c == '{' {
            if s.peek_at(1) == Some('{') {
                return None;
            }
            let mut i = 1;
            while let Some(c) = s.peek_at(i) {
                if c == '}' {
                    return Some(i + 1);
                }
                if c == '{' || c == '"' || c == '\'' || c == ' ' {
                    return None;
                }
                i += 1;
            }
            return None;
        }
        None
    }

    fn regex_token(&mut self, s: &mut Scanner) -> bool {
        let c = s.peek().unwrap();
        if c == '\\' {
            match s.peek_at(1) {
                Some(d) if "dDwWsS".contains(d) => {
                    s.emit(2, Class::Number);
                }
                Some(d) if "bBAZz".contains(d) => {
                    s.emit(2, Class::Keyword);
                }
                Some(_) => {
                    s.emit(2, Class::Escape);
                }
                None => {
                    s.emit(1, Class::String);
                }
            }
            return true;
        }
        match c {
            '+' | '*' | '?' | '|' => {
                s.emit(1, Class::Plain);
                true
            }
            '^' | '$' => {
                s.emit(1, Class::Keyword);
                true
            }
            '.' => {
                s.emit(1, Class::Number);
                true
            }
            '{' => {
                let mut i = 1;
                while s.peek_at(i).is_some_and(|c| c.is_ascii_digit() || c == ',') {
                    i += 1;
                }
                if i > 1 && s.peek_at(i) == Some('}') {
                    s.emit(i + 1, Class::Plain);
                    true
                } else {
                    false
                }
            }
            '[' => {
                // character class
                s.emit(1, Class::Number);
                if s.peek() == Some('^') {
                    s.emit(1, Class::Plain);
                }
                while let Some(c) = s.peek() {
                    if c == '\'' || c == '"' {
                        break;
                    }
                    if c == '\\' && s.peek_at(1).is_some() {
                        s.emit(2, Class::Escape);
                        continue;
                    }
                    s.emit(1, Class::Number);
                    if c == ']' {
                        break;
                    }
                }
                true
            }
            _ => false,
        }
    }

    fn fstring_body(&mut self, s: &mut Scanner, st: StrState) {
        // inside of a replacement field, after the opening brace
        let mut depth = 0usize;
        while !s.eof() {
            let c = s.peek().unwrap();
            if Self::string_end(s, &st) {
                // the string ends before the field is closed
                s.emit(if st.triple { 3 } else { 1 }, Class::Plain);
                self.string = None;
                return;
            }
            match c {
                '}' if depth == 0 => {
                    s.emit(1, Class::Plain);
                    return;
                }
                '!' if depth == 0 && s.peek_at(1).is_some_and(|c| "rsa".contains(c)) => {
                    s.emit(2, Class::Keyword);
                }
                ':' if depth == 0 => {
                    s.emit(1, Class::Number);
                    while let Some(c) = s.peek() {
                        if c == '}' || c == '{' || Self::string_end(s, &st) {
                            break;
                        }
                        s.emit(1, Class::Number);
                    }
                    if s.peek() == Some('{') {
                        // nested replacement field
                        s.emit(1, Class::Plain);
                        while let Some(c) = s.peek() {
                            if c == '}' || Self::string_end(s, &st) {
                                break;
                            }
                            s.emit(1, Class::Plain);
                        }
                        if s.peek() == Some('}') {
                            s.emit(1, Class::Plain);
                        }
                    }
                }
                '(' | '[' | '{' => {
                    depth += 1;
                    s.emit(1, Class::Plain);
                }
                ')' | ']' | '}' => {
                    depth = depth.saturating_sub(1);
                    s.emit(1, Class::Plain);
                }
                '"' | '\'' if c != st.quote => {
                    // nested string
                    s.emit(1, Class::Plain);
                    while let Some(d) = s.peek() {
                        if d == c {
                            break;
                        }
                        s.emit(1, Class::String);
                    }
                    if s.peek() == Some(c) {
                        s.emit(1, Class::Plain);
                    }
                }
                _ => {
                    if c.is_ascii_digit() {
                        let n = Self::number_len(s);
                        if n.0 > 0 {
                            s.emit(n.0, Class::Number);
                            s.emit(n.1, Class::Keyword);
                            continue;
                        }
                    }
                    if is_ident_start(c) {
                        let len = s.ident_len();
                        let word = s.word_at(s.pos, len);
                        let class = if CONSTANTS.contains(&word.as_str()) {
                            Class::Number
                        } else if word == "self" {
                            Class::Variable
                        } else {
                            Class::Plain
                        };
                        s.emit(len, class);
                        continue;
                    }
                    s.emit(1, Class::Plain);
                }
            }
        }
    }

    fn number_len(s: &Scanner) -> (usize, usize) {
        let chars = &s.chars;
        let n = chars.len();
        let start = s.pos;
        let mut i = start;
        let is = |i: usize, f: &dyn Fn(char) -> bool| i < n && f(chars[i]);
        if chars[i] == '0' && is(i + 1, &|c| c == 'x' || c == 'X') {
            i += 2;
            while is(i, &|c| c.is_ascii_hexdigit() || c == '_') {
                i += 1;
            }
        } else if chars[i] == '0' && is(i + 1, &|c| c == 'o' || c == 'O') {
            i += 2;
            while is(i, &|c| c.is_digit(8) || c == '_') {
                i += 1;
            }
        } else if chars[i] == '0' && is(i + 1, &|c| c == 'b' || c == 'B') {
            i += 2;
            while is(i, &|c| c == '0' || c == '1' || c == '_') {
                i += 1;
            }
        } else {
            while is(i, &|c| c.is_ascii_digit() || c == '_') {
                i += 1;
            }
            if is(i, &|c| c == '.') {
                i += 1;
                while is(i, &|c| c.is_ascii_digit() || c == '_') {
                    i += 1;
                }
            }
            if is(i, &|c| c == 'e' || c == 'E') {
                let mut j = i + 1;
                if is(j, &|c| c == '+' || c == '-') {
                    j += 1;
                }
                if is(j, &|c| c.is_ascii_digit()) {
                    while is(j, &|c| c.is_ascii_digit() || c == '_') {
                        j += 1;
                    }
                    i = j;
                }
            }
        }
        let mut suffix = 0;
        if is(i, &|c| c == 'j' || c == 'J' || c == 'l' || c == 'L') {
            suffix = 1;
        }
        if is(i + suffix, &is_ident_char) {
            return (0, 0);
        }
        (i - start, suffix)
    }

    fn string_prefix(s: &Scanner) -> Option<(usize, StrState)> {
        let mut i = 0;
        let mut raw = false;
        let mut format = false;
        let mut bytes = false;
        while i < 2 {
            match s.peek_at(i) {
                Some('r') | Some('R') => {
                    if raw {
                        return None;
                    }
                    raw = true;
                    if s.peek_at(i) == Some('R') {
                        // upper case R does not get regex highlighting
                        bytes = !format;
                        if format {
                            raw = true;
                        }
                    }
                }
                Some('f') | Some('F') => format = true,
                Some('b') | Some('B') => bytes = true,
                Some('u') | Some('U') => {}
                _ => break,
            }
            i += 1;
        }
        let quote = s.peek_at(i)?;
        if quote != '"' && quote != '\'' {
            return None;
        }
        let triple = s.peek_at(i + 1) == Some(quote) && s.peek_at(i + 2) == Some(quote);
        Some((
            i,
            StrState {
                quote,
                triple,
                raw,
                format,
                bytes,
                docstring: false,
            },
        ))
    }

    fn token(&mut self, s: &mut Scanner, first_token: bool) {
        let c = s.peek().unwrap();
        if c == '#' {
            s.emit_rest(Class::Comment);
            return;
        }
        // strings
        if c == '"' || c == '\'' || (is_ident_start(c) && (s.pos == 0 || !is_ident_char(s.prev().unwrap()))) {
            if let Some((prefix, mut st)) = Self::string_prefix(s) {
                if prefix == 0 || !is_ident_char(s.peek_at(prefix + 1).unwrap_or(' ')) || true {
                    if first_token && st.triple && prefix == 0 {
                        st.docstring = true;
                        s.emit(3, Class::Comment);
                        self.string = Some(st);
                        return;
                    }
                    s.emit(prefix, Class::Keyword);
                    s.emit(if st.triple { 3 } else { 1 }, Class::Plain);
                    self.string = Some(st);
                    return;
                }
            }
        }
        if c.is_ascii_digit() || (c == '.' && s.peek_at(1).is_some_and(|c| c.is_ascii_digit())) {
            if s.pos == 0 || !is_ident_char(s.prev().unwrap()) {
                let (n, suffix) = Self::number_len(s);
                if n > 0 {
                    s.emit(n, Class::Number);
                    s.emit(suffix, Class::Keyword);
                    return;
                }
            }
        }
        if s.starts_with("...") {
            s.emit(3, Class::Number);
            return;
        }
        if c == '@' && first_token {
            s.emit(1, Class::Plain);
            self.decorator(s);
            return;
        }
        if is_ident_start(c) {
            self.identifier(s);
            return;
        }
        self.punctuation(s, c);
    }

    fn decorator(&mut self, s: &mut Scanner) {
        // dotted name, the last component is highlighted
        loop {
            let len = s.ident_len();
            if len == 0 {
                return;
            }
            let word = s.word_at(s.pos, len);
            if s.chars.get(s.pos + len) == Some(&'.') {
                s.emit(len + 1, Class::Plain);
                continue;
            }
            let class = if BUILTIN_FUNCTIONS.contains(&word.as_str()) {
                Class::Support
            } else {
                Class::Variable
            };
            s.emit(len, class);
            return;
        }
    }

    fn punctuation(&mut self, s: &mut Scanner, c: char) {
        let class_color = self.class.is_some() && (self.class == Some(ClassState::Header) || self.in_class_bases());
        match c {
            '(' | '[' | '{' => {
                let kind = if c == '(' && self.expect_params {
                    self.expect_params = false;
                    self.param_name = true;
                    Paren::Params
                } else if c == '(' && self.class == Some(ClassState::Header) && !self.in_class_bases() {
                    Paren::ClassBases
                } else if c == '(' && s.prev_non_ws(s.pos).is_some_and(|(_, p)| is_ident_char(p) || p == ')' || p == ']') {
                    Paren::Call
                } else {
                    Paren::Group
                };
                self.parens.push((kind, c));
                let class = if class_color || kind == Paren::ClassBases { Class::Embedded } else { Class::Plain };
                s.emit(1, class);
                return;
            }
            ')' | ']' | '}' => {
                let popped = self.parens.pop();
                if let Some((Paren::ClassBases, _)) = popped {
                    s.emit(1, Class::Embedded);
                    self.class = Some(ClassState::AfterBases);
                    return;
                }
                let class = if class_color { Class::Embedded } else { Class::Plain };
                s.emit(1, class);
                return;
            }
            ',' => {
                if self.top_paren() == Some(Paren::Params) {
                    self.param_name = true;
                }
                if self.lambda && self.parens.is_empty() {
                    self.param_name = true;
                }
            }
            '=' => {
                if self.top_paren() == Some(Paren::Params) && s.peek_at(1) != Some('=') {
                    self.param_name = false;
                }
            }
            ':' => {
                if self.top_paren() == Some(Paren::Params) {
                    self.param_name = false;
                }
                if self.lambda && self.parens.is_empty() {
                    self.lambda = false;
                    self.param_name = false;
                }
                if self.class.is_some() && !self.in_class_bases() {
                    self.class = None;
                    s.emit(1, Class::Embedded);
                    return;
                }
            }
            '*' => {}
            _ => {}
        }
        let class = if class_color { Class::Embedded } else { Class::Plain };
        s.emit(1, class);
    }

    fn identifier(&mut self, s: &mut Scanner) {
        let start = s.pos;
        let len = s.ident_len();
        let word = s.word_at(start, len);
        let after = start + len;
        let next_non_ws = s.next_non_ws(after);
        let prev_dot = s.prev_non_ws(start).is_some_and(|(_, c)| c == '.');

        // class header
        if let Some(state) = self.class {
            if state == ClassState::Header && !self.in_class_bases() && !self.class_name_done {
                self.class_name_done = true;
                s.emit(len, Class::Type);
                return;
            }
            if self.in_class_bases() {
                if next_non_ws.is_some_and(|(i, c)| c == '=' && s.chars.get(i + 1) != Some(&'=')) {
                    s.emit(len, Class::Variable);
                    return;
                }
                if self.top_paren() == Some(Paren::ClassBases) {
                    // dotted base class names
                    let mut end = after;
                    while s.chars.get(end) == Some(&'.') && s.chars.get(end + 1).is_some_and(|c| is_ident_start(*c)) {
                        end += 1;
                        while end < s.chars.len() && is_ident_char(s.chars[end]) {
                            end += 1;
                        }
                    }
                    s.emit(end - start, Class::String);
                    return;
                }
                s.emit(len, Class::Embedded);
                return;
            }
        }

        if self.expect_def_name {
            self.expect_def_name = false;
            let class = if word.starts_with("__") && word.ends_with("__") && word.len() > 4 {
                Class::Support
            } else {
                Class::Function
            };
            s.emit(len, class);
            self.expect_params = true;
            return;
        }

        if (self.top_paren() == Some(Paren::Params) || (self.lambda && self.parens.is_empty())) && self.param_name {
            s.emit(len, Class::Variable);
            self.param_name = false;
            return;
        }

        if word == "async" {
            // async def / async with / async for
            if let Some((i, c)) = next_non_ws {
                if is_ident_start(c) {
                    let mut j = i;
                    while j < s.chars.len() && is_ident_char(s.chars[j]) {
                        j += 1;
                    }
                    let next_word: String = s.chars[i..j].iter().collect();
                    if next_word == "with" || next_word == "for" {
                        if next_word == "for" {
                            self.for_statement = true;
                        }
                        s.emit(j - start, Class::Keyword);
                        return;
                    }
                }
            }
        }

        if KEYWORDS.contains(&word.as_str()) && !prev_dot {
            match word.as_str() {
                "def" => self.expect_def_name = true,
                "class" => {
                    self.class = Some(ClassState::Header);
                    self.class_name_done = false;
                }
                "lambda" => {
                    self.lambda = true;
                    self.param_name = true;
                }
                "for" => self.for_statement = true,
                "import" | "from" => {
                    s.emit(len, Class::Keyword);
                    // relative imports
                    let mut i = s.pos;
                    while i < s.chars.len() && s.chars[i] == ' ' {
                        i += 1;
                    }
                    if word == "from" && s.chars.get(i) == Some(&'.') {
                        s.emit(i - s.pos, Class::Plain);
                        let mut n = 0;
                        while s.peek_at(n) == Some('.') {
                            n += 1;
                        }
                        s.emit(n, Class::Keyword);
                    }
                    return;
                }
                _ => {}
            }
            s.emit(len, Class::Keyword);
            return;
        }
        if word == "in" && self.for_statement {
            self.for_statement = false;
            s.emit(len, Class::Keyword);
            return;
        }
        if CONSTANTS.contains(&word.as_str()) {
            s.emit(len, Class::Number);
            return;
        }
        if word == "self" || word == "cls" {
            s.emit(len, Class::Variable);
            return;
        }
        // keyword arguments
        if self.top_paren() == Some(Paren::Call) {
            if let Some((i, '=')) = next_non_ws {
                if s.chars.get(i + 1) != Some(&'=') {
                    s.emit(len, Class::Variable);
                    return;
                }
            }
        }
        let is_call = next_non_ws.is_some_and(|(_, c)| c == '(');
        if BUILTIN_FUNCTIONS.contains(&word.as_str()) && !prev_dot {
            s.emit(len, Class::Support);
            return;
        }
        if is_call {
            let class = if word.starts_with("__") && word.ends_with("__") && word.len() > 4 {
                Class::Support
            } else if BUILTIN_TYPES.contains(&word.as_str()) && !prev_dot {
                Class::Plain
            } else {
                Class::Function
            };
            s.emit(len, class);
            return;
        }
        if is_constant(&word) {
            s.emit(len, Class::Variable);
            return;
        }
        s.emit(len, Class::Plain);
    }
}

const BUILTIN_TYPES: &[&str] = &[
    "bool", "bytearray", "bytes", "complex", "dict", "float", "frozenset", "int", "list",
    "long", "memoryview", "object", "set", "slice", "str", "tuple", "unicode", "Exception",
    "BaseException", "ArithmeticError", "AssertionError", "AttributeError", "BufferError",
    "EOFError", "EnvironmentError", "FloatingPointError", "GeneratorExit", "IOError",
