#!/usr/bin/env python3
# MARKER
"""A small example module."""

import argparse
import logging
from typing import List, Optional, Dict

logger = logging.getLogger(__name__)

DEFAULT_TIMEOUT = 30


class Config:
    """Configuration holder."""

    def __init__(self, name: str, values: Optional[Dict[str, int]] = None) -> None:
        self.name = name
        self.values = values or {}

    def get(self, key, default=0):
        # Return the value for key
        return self.values.get(key, default)

    def __repr__(self):
        return f"Config(name={self.name!r}, values={len(self.values)})"


