//! Highlighting of JavaScript source files.

use super::scanner::{is_ident_char, is_ident_start, Class, Scanner};

const KEYWORDS: &[&str] = &[
    "async", "await", "break", "case", "catch", "class", "const", "continue", "debugger",
    "default", "do", "else", "export", "extends", "finally", "for", "from", "function", "if",
    "import", "let", "return", "static", "switch", "throw", "try", "var", "while", "with",
    "yield", "as", "get", "set",
];

const CONSTANTS: &[&str] = &["true", "false", "null", "undefined", "NaN", "Infinity"];

const OPERATOR_WORDS: &[&str] = &["new", "typeof", "instanceof", "delete", "void", "in", "of"];

const BUILTIN_CLASSES: &[&str] = &[
    "Array", "ArrayBuffer", "Boolean", "DataView", "Date", "Error", "EvalError", "Float32Array",
    "Float64Array", "Function", "Int16Array", "Int32Array", "Int8Array", "Map", "Math", "Number",
    "Object", "Promise", "Proxy", "RangeError", "ReferenceError", "Reflect", "RegExp", "Set",
    "String", "Symbol", "SyntaxError", "TypeError", "URIError", "Uint16Array", "Uint32Array",
    "Uint8Array", "Uint8ClampedArray", "WeakMap", "WeakSet",
];

const BUILTIN_FUNCTIONS: &[&str] = &[
    "decodeURI", "decodeURIComponent", "encodeURI", "encodeURIComponent", "escape", "eval",
    "isFinite", "isNaN", "parseFloat", "parseInt", "unescape", "setTimeout", "setInterval",
    "clearTimeout", "clearInterval",
];

const SUPPORT_OBJECTS: &[&str] = &["window", "console", "document", "process", "module", "exports", "global"];

const CONSOLE_METHODS: &[&str] = &[
    "log", "error", "warn", "info", "debug", "trace", "dir", "table", "time", "timeEnd", "assert",
    "count", "group", "groupEnd",
];

const DOM_METHODS: &[&str] = &[
    "getElementById", "getElementsByClassName", "getElementsByTagName", "querySelector",
    "querySelectorAll", "createElement",
];

#[derive(Clone, Copy, PartialEq, Eq)]
enum Str {
    Quote(char),
    Template,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Brace {
    Block,
    Class,
    Object,
    Template,
}

#[derive(Default)]
pub struct JavaScriptHighlighter {
    comment: bool,
    string: Option<Str>,
    braces: Vec<Brace>,
    /// Waiting for the name of a function.
    expect_fn_name: bool,
    /// Waiting for the parameter list of a function.
    expect_params: bool,
    params_depth: usize,
    /// Declaration keyword seen, next identifier is declared.
    declaration: bool,
    expect_class_name: bool,
    class_header: bool,
    expect_class_body: bool,
    /// Last significant token allows a regular expression literal.
    regex_allowed: bool,
    paren_depth: usize,
}

fn is_operator(c: char) -> bool {
    "=+-*/%<>!&|^~?".contains(c)
}

impl JavaScriptHighlighter {
    fn in_class(&self) -> bool {
        self.braces.iter().any(|b| *b == Brace::Class)
    }

    fn plain(&self) -> Class {
        if self.in_class() || self.class_header {
            Class::Embedded
        } else {
            Class::Plain
        }
    }

    pub fn highlight_line(&mut self, line: &str) -> Vec<(Class, String)> {
        let mut s = Scanner::new(line);
        if s.chars.is_empty() {
            return s.out;
        }
        self.regex_allowed = true;
        while !s.eof() {
            if self.comment {
                if s.starts_with("*/") {
                    s.emit(2, Class::Comment);
                    self.comment = false;
                } else {
                    s.emit(1, Class::Comment);
                }
                continue;
            }
            if let Some(st) = self.string {
                self.string_body(&mut s, st);
                continue;
            }
            self.token(&mut s);
        }
        s.out
    }

    fn escape_len(s: &Scanner) -> usize {
        if s.peek() != Some('\\') {
            return 0;
        }
        match s.peek_at(1) {
            Some('x') => 4,
            Some('u') => {
                if s.peek_at(2) == Some('{') {
                    let mut i = 3;
                    while s.peek_at(i).is_some_and(|c| c != '}') {
                        i += 1;
                    }
                    i + 1
                } else {
                    6
                }
            }
            Some(_) => 2,
            None => 1,
        }
    }

    fn string_body(&mut self, s: &mut Scanner, st: Str) {
        while !s.eof() {
            match st {
                Str::Quote(q) => {
                    if s.peek() == Some(q) {
                        s.emit(1, Class::Plain);
                        self.string = None;
                        self.regex_allowed = false;
                        return;
                    }
                }
                Str::Template => {
                    if s.peek() == Some('`') {
                        s.emit(1, Class::Plain);
                        self.string = None;
                        self.regex_allowed = false;
                        return;
                    }
                    if s.starts_with("${") {
                        s.emit(2, Class::Plain);
                        self.braces.push(Brace::Template);
                        self.string = None;
                        self.regex_allowed = true;
                        return;
                    }
                }
            }
            let n = Self::escape_len(s);
            if n > 0 {
                s.emit(n, Class::Escape);
                continue;
            }
            s.emit(1, Class::String);
        }
        if let Str::Quote(_) = st {
            self.string = None;
        }
    }

    fn token(&mut self, s: &mut Scanner) {
        let c = s.peek().unwrap();
        if c.is_whitespace() {
            let class = self.plain();
            s.emit(1, class);
            return;
        }
        if s.starts_with("//") {
            s.emit_rest(Class::Comment);
            return;
        }
        if s.starts_with("/*") {
            s.emit(2, Class::Comment);
            self.comment = true;
            return;
        }
        if c == '"' || c == '\'' {
            s.emit(1, Class::Plain);
            self.string = Some(Str::Quote(c));
            return;
        }
        if c == '`' {
            s.emit(1, Class::Plain);
            self.string = Some(Str::Template);
            return;
        }
        if c == '/' && self.regex_allowed {
            if self.regex(s) {
                return;
            }
        }
        if c.is_ascii_digit() || (c == '.' && s.peek_at(1).is_some_and(|c| c.is_ascii_digit())) {
            if s.pos == 0 || !is_ident_char(s.prev().unwrap()) {
                let n = number_len(s);
                if n > 0 {
                    s.emit(n, Class::Number);
                    self.regex_allowed = false;
                    return;
                }
            }
        }
        if is_ident_start(c) || c == '$' {
            self.identifier(s);
            return;
        }
        self.punctuation(s, c);
    }

    fn regex(&mut self, s: &mut Scanner) -> bool {
        // find the end of the regular expression on this line
        let mut i = s.pos + 1;
        let mut in_class = false;
        let mut end = None;
        while i < s.chars.len() {
            let c = s.chars[i];
            if c == '\\' {
                i += 2;
                continue;
            }
            if c == '[' {
                in_class = true;
            } else if c == ']' {
                in_class = false;
            } else if c == '/' && !in_class {
                end = Some(i);
                break;
            }
            i += 1;
        }
        let end = match end {
            Some(e) if e > s.pos + 1 => e,
            _ => return false,
        };
        s.emit(1, Class::Plain);
        while s.pos < end {
            let c = s.peek().unwrap();
            if c == '\\' {
                s.emit(2, Class::Escape);
            } else if "+*?|(){}^$.".contains(c) {
                s.emit(1, Class::Plain);
            } else {
                s.emit(1, Class::Support);
            }
        }
        s.emit(1, Class::Plain);
        let mut flags = 0;
        while s.peek_at(flags).is_some_and(|c| c.is_ascii_alphabetic()) {
            flags += 1;
        }
        s.emit(flags, Class::Keyword);
        self.regex_allowed = false;
        true
    }

    fn punctuation(&mut self, s: &mut Scanner, c: char) {
        self.expect_fn_name = false;
        let plain = self.plain();
        match c {
            '{' => {
                let kind = if self.expect_class_body {
                    self.expect_class_body = false;
                    self.class_header = false;
                    Brace::Class
                } else if self.regex_allowed && !self.expect_params_body() {
                    // `{` in expression position is an object literal
                    let prev = s.prev_non_ws(s.pos).map(|(_, c)| c);
                    match prev {
                        Some('=') | Some('(') | Some(',') | Some(':') | Some('[') | Some('?') => Brace::Object,
                        _ => Brace::Block,
                    }
                } else {
                    Brace::Block
                };
                self.braces.push(kind);
                self.declaration = false;
                s.emit(1, if kind == Brace::Class { Class::Embedded } else { plain });
                self.regex_allowed = true;
                return;
            }
            '}' => {
                let popped = self.braces.pop();
                if popped == Some(Brace::Template) {
                    s.emit(1, Class::Plain);
                    self.string = Some(Str::Template);
                    return;
                }
                let class = if popped == Some(Brace::Class) { Class::Embedded } else { self.plain() };
                s.emit(1, class);
                self.regex_allowed = true;
                return;
            }
            '(' => {
                self.paren_depth += 1;
                if self.expect_params {
                    self.expect_params = false;
                    self.params_depth = self.paren_depth;
                }
                self.regex_allowed = true;
            }
            ')' => {
                if self.params_depth == self.paren_depth {
                    self.params_depth = 0;
                }
                self.paren_depth = self.paren_depth.saturating_sub(1);
                self.regex_allowed = false;
            }
            ']' => self.regex_allowed = false,
            ';' => {
                self.declaration = false;
                self.regex_allowed = true;
            }
            ',' => self.regex_allowed = true,
            _ => {
                self.regex_allowed = true;
            }
        }
        if s.starts_with("=>") {
            s.emit(2, Class::Keyword);
            self.regex_allowed = true;
            return;
        }
        if c == '*' && self.import_star(s) {
            s.emit(1, Class::Number);
            return;
        }
        if c == '=' && s.peek_at(1) != Some('=') {
            self.declaration = false;
        }
        if is_operator(c) {
            s.emit(1, Class::Plain);
        } else {
            s.emit(1, plain);
        }
    }

    fn expect_params_body(&self) -> bool {
        false
    }

    fn import_star(&self, s: &Scanner) -> bool {
        let line: String = s.chars.iter().collect();
        let trimmed = line.trim_start();
        (trimmed.starts_with("import") || trimmed.starts_with("export"))
            && s.next_non_ws(s.pos + 1).is_some_and(|(i, _)| s.chars[i..].starts_with(&['a', 's']))
    }

    fn identifier(&mut self, s: &mut Scanner) {
        let start = s.pos;
        let mut len = 0;
        while start + len < s.chars.len() && (is_ident_char(s.chars[start + len]) || s.chars[start + len] == '$') {
            len += 1;
        }
        let word = s.word_at(start, len);
        let after = start + len;
        let next = s.next_non_ws(after);
        let next_char = next.map(|(_, c)| c);
        let prev_dot = start > 0 && s.chars[start - 1] == '.';
        let is_call = next_char == Some('(');
        let plain = self.plain();
        self.regex_allowed = false;

        if self.expect_class_name {
            self.expect_class_name = false;
            s.emit(len, Class::Type);
            return;
        }
        if self.class_header && word == "extends" {
            s.emit(len, Class::Keyword);
            return;
        }
        if self.class_header {
            s.emit(len, Class::String);
            return;
        }
        if self.expect_fn_name {
            self.expect_fn_name = false;
            s.emit(len, Class::Function);
            self.expect_params = true;
            return;
        }
        if self.params_depth > 0 && self.paren_depth >= self.params_depth {
            // parameters are not highlighted
            s.emit(len, Class::Plain);
            return;
        }
        if prev_dot {
            if is_call {
                let object = self.object_before(s, start);
                let class = if object == "console" && CONSOLE_METHODS.contains(&word.as_str())
                    || object == "document" && DOM_METHODS.contains(&word.as_str())
                {
                    Class::Support
                } else {
                    Class::Function
                };
                s.emit(len, class);
            } else if next_char == Some('=') && s.chars.get(next.unwrap().0 + 1) != Some(&'=') && self.function_follows(s, next.unwrap().0 + 1) {
                s.emit(len, Class::Function);
            } else {
                s.emit(len, plain);
            }
            return;
        }
        if KEYWORDS.contains(&word.as_str()) {
            let is_keyword = match word.as_str() {
                "get" | "set" | "static" => self.in_class(),
                "as" | "from" => true,
                _ => true,
            };
            if is_keyword {
                match word.as_str() {
                    "function" => {
                        if s.chars.get(after) == Some(&'*') {
                            s.emit(len + 1, Class::Keyword);
                        } else {
                            s.emit(len, Class::Keyword);
                        }
                        self.expect_fn_name = true;
                        self.expect_params = true;
                        self.regex_allowed = false;
                        return;
                    }
                    "class" => {
                        self.expect_class_name = true;
                        self.class_header = true;
                        self.expect_class_body = true;
                    }
                    "const" | "let" | "var" => self.declaration = true,
                    "return" | "case" | "throw" | "yield" | "await" | "typeof" => self.regex_allowed = true,
                    _ => {}
                }
                if word == "async" && self.in_class() && !self.braces_in_method() {
                    s.emit(len, Class::Function);
                    return;
                }
                s.emit(len, Class::Keyword);
                return;
            }
        }
        if CONSTANTS.contains(&word.as_str()) {
            s.emit(len, Class::Number);
            return;
        }
        if OPERATOR_WORDS.contains(&word.as_str()) {
            self.regex_allowed = true;
            s.emit(len, Class::Plain);
            return;
        }
        if word == "this" {
            s.emit(len, Class::Variable);
            return;
        }
        if word == "super" {
            s.emit(len, Class::Support);
            return;
        }
        // method definitions in classes and object literals
        if (self.in_class_body_top() || self.top_brace() == Some(Brace::Object)) && is_call && self.method_definition(s, after) {
            s.emit(len, Class::Function);
            return;
        }
        if self.top_brace() == Some(Brace::Object) && next_char == Some(':') {
            if self.function_follows(s, next.unwrap().0 + 1) {
                s.emit(len, Class::Function);
            } else {
                s.emit(len, Class::Plain);
            }
            return;
        }
        if self.declaration {
            if next_char == Some('=') && s.chars.get(next.unwrap().0 + 1) != Some(&'=') && self.function_follows(s, next.unwrap().0 + 1) {
                s.emit(len, Class::Function);
                return;
            }
            if next_char == Some(':') {
                // destructuring key
                s.emit(len, Class::Plain);
                return;
            }
            s.emit(len, Class::Variable);
            return;
        }
        if is_call {
            let class = if BUILTIN_FUNCTIONS.contains(&word.as_str()) {
                Class::Support
            } else {
                Class::Function
            };
            s.emit(len, class);
            return;
        }
        if next_char == Some('=') && s.chars.get(next.unwrap().0 + 1) == Some(&'>') {
            // single arrow function parameter
            s.emit(len, Class::Plain);
            return;
        }
        if next_char == Some(':') && s.chars.get(next.unwrap().0 + 1) != Some(&':') && self.top_brace() != Some(Brace::Object) && s.prev_non_ws(start).is_none_or(|(_, c)| c == ';' || c == '{' || c == '}') {
            // label
            s.emit(len, Class::Plain);
            return;
        }
        if BUILTIN_CLASSES.contains(&word.as_str()) {
            s.emit(len, Class::Type);
            return;
        }
        if SUPPORT_OBJECTS.contains(&word.as_str()) {
            s.emit(len, plain);
            return;
        }
        if next_char == Some('.') && next.unwrap().0 == after && self.assigns_function_to_property(s, after) {
            s.emit(len, Class::Type);
            return;
        }
        s.emit(len, Class::Variable);
    }

    fn top_brace(&self) -> Option<Brace> {
        self.braces.last().copied()
    }

    fn in_class_body_top(&self) -> bool {
        self.top_brace() == Some(Brace::Class)
    }

    fn braces_in_method(&self) -> bool {
        self.top_brace() != Some(Brace::Class)
    }

    fn method_definition(&self, s: &Scanner, after: usize) -> bool {
        // name(...) { -- find the matching parenthesis and check for a brace
        let mut i = after;
        while i < s.chars.len() && s.chars[i] != '(' {
            i += 1;
        }
        let mut depth = 0;
        while i < s.chars.len() {
            match s.chars[i] {
                '(' => depth += 1,
                ')' => {
                    depth -= 1;
                    if depth == 0 {
                        return s.next_non_ws(i + 1).is_some_and(|(_, c)| c == '{');
                    }
                }
                _ => {}
            }
            i += 1;
        }
        false
    }

    fn function_follows(&self, s: &Scanner, from: usize) -> bool {
        let rest: String = s.chars[from.min(s.chars.len())..].iter().collect();
        let rest = rest.trim_start();
        if rest.starts_with("function") || rest.starts_with("async") {
            return true;
        }
        // arrow functions: `(..) =>` or `x =>`
        if rest.starts_with('(') {
            let mut depth = 0;
            for (i, c) in rest.char_indices() {
                match c {
                    '(' => depth += 1,
                    ')' => {
                        depth -= 1;
                        if depth == 0 {
                            return rest[i + 1..].trim_start().starts_with("=>");
                        }
                    }
                    _ => {}
                }
            }
            return false;
        }
        let ident: String = rest.chars().take_while(|c| is_ident_char(*c) || *c == '$').collect();
        !ident.is_empty() && rest[ident.len()..].trim_start().starts_with("=>")
    }

    fn assigns_function_to_property(&self, s: &Scanner, after: usize) -> bool {
        // obj.prop = function ...
        let mut i = after + 1;
        while i < s.chars.len() && (is_ident_char(s.chars[i]) || s.chars[i] == '$') {
            i += 1;
        }
        match s.next_non_ws(i) {
            Some((j, '=')) if s.chars.get(j + 1) != Some(&'=') => self.function_follows(s, j + 1),
            _ => false,
        }
    }

    fn object_before(&self, s: &Scanner, start: usize) -> String {
        let mut i = start - 1;
        let end = i;
        while i > 0 && (is_ident_char(s.chars[i - 1]) || s.chars[i - 1] == '$') {
            i -= 1;
        }
        s.chars[i..end].iter().collect()
    }
}

fn number_len(s: &Scanner) -> usize {
    let chars = &s.chars;
    let n = chars.len();
    let start = s.pos;
    let mut i = start;
    let is = |i: usize, f: &dyn Fn(char) -> bool| i < n && f(chars[i]);
    if chars[i] == '0' && is(i + 1, &|c| "xXoObB".contains(c)) {
        i += 2;
        while is(i, &|c| c.is_ascii_hexdigit() || c == '_') {
            i += 1;
        }
    } else {
        while is(i, &|c| c.is_ascii_digit() || c == '_') {
            i += 1;
        }
        if is(i, &|c| c == '.') {
            i += 1;
            while is(i, &|c| c.is_ascii_digit() || c == '_') {
                i += 1;
            }
        }
        if is(i, &|c| c == 'e' || c == 'E') {
            let mut j = i + 1;
            if is(j, &|c| c == '+' || c == '-') {
                j += 1;
            }
            if is(j, &|c| c.is_ascii_digit()) {
                while is(j, &|c| c.is_ascii_digit()) {
                    j += 1;
                }
                i = j;
            }
        }
    }
    if is(i, &|c| c == 'n') {
        i += 1;
    }
    if is(i, &|c| is_ident_char(c)) {
        return 0;
    }
    i - start
}
