//! Highlighting of JSON files.

use super::scanner::{Class, Scanner};

#[derive(Default)]
pub struct JsonHighlighter {
    comment: bool,
    string: bool,
}

impl JsonHighlighter {
    pub fn highlight_line(&mut self, line: &str) -> Vec<(Class, String)> {
        let mut s = Scanner::new(line);
        while !s.eof() {
            if self.comment {
                if s.starts_with("*/") {
                    s.emit(2, Class::Comment);
                    self.comment = false;
                } else {
                    s.emit(1, Class::Comment);
                }
                continue;
            }
            if self.string {
                match s.peek().unwrap() {
                    '"' => {
                        s.emit(1, Class::Plain);
                        self.string = false;
                    }
                    '\\' => {
                        let n = match s.peek_at(1) {
                            Some('u') => 6,
                            Some(_) => 2,
                            None => 1,
                        };
                        s.emit(n, Class::Escape);
                    }
                    _ => s.emit(1, Class::String),
                }
                continue;
            }
            let c = s.peek().unwrap();
            if s.starts_with("//") {
                s.emit_rest(Class::Comment);
            } else if s.starts_with("/*") {
                s.emit(2, Class::Comment);
                self.comment = true;
            } else if c == '"' {
                s.emit(1, Class::Plain);
                self.string = true;
            } else if c == '-' || c.is_ascii_digit() {
                let mut i = 1;
                while s
                    .peek_at(i)
                    .is_some_and(|c| c.is_ascii_digit() || ".eE+-".contains(c))
                {
                    i += 1;
                }
                s.emit(i, Class::Number);
            } else if s.starts_with("true") || s.starts_with("null") {
                s.emit(4, Class::Number);
            } else if s.starts_with("false") {
                s.emit(5, Class::Number);
            } else {
                s.emit(1, Class::Plain);
            }
        }
        s.out
    }
}
