    /// List items and block quotes
    Red,
    Fence(char, usize),
}

pub struct MarkdownHighlighter {
    block: Block,
}

impl Default for MarkdownHighlighter {
    fn default() -> Self {
        Self { block: Block::Normal }
    }
}

fn leading_spaces(line: &str) -> usize {
    line.chars().take_while(|c| *c == ' ').count()
}

fn is_list_item(line: &str) -> bool {
    let indent = leading_spaces(line);
    let rest = &line[indent..];
    let mut chars = rest.chars();
    match chars.next() {
        Some('*') | Some('+') | Some('-') => matches!(chars.next(), Some(' ') | Some('\t')),
        Some(c) if c.is_ascii_digit() => {
            let digits = rest.chars().take_while(|c| c.is_ascii_digit()).count();
            let after: Vec<char> = rest.chars().skip(digits).take(2).collect();
            after.len() == 2 && (after[0] == '.' || after[0] == ')') && (after[1] == ' ' || after[1] == '\t')
        }
        _ => false,
    }
}

fn is_quote(line: &str) -> bool {
    let indent = leading_spaces(line);
    indent <= 3 && line[indent..].starts_with('>')
}

fn fence(line: &str) -> Option<(char, usize)> {
    let indent = leading_spaces(line);
    if indent > 3 {
        return None;
    }
    let rest = &line[indent..];
    let c = rest.chars().next()?;
    if c != '`' && c != '~' {
        return None;
    }
    let n = rest.chars().take_while(|x| *x == c).count();
    if n >= 3 {
        Some((c, n))
    } else {
        None
    }
}

fn heading_level(line: &str) -> Option<usize> {
    let n = line.chars().take_while(|c| *c == '#').count();
    if (1..=6).contains(&n) && matches!(line.chars().nth(n), Some(' ') | Some('\t') | None) {
        Some(n)
    } else {
        None
    }
}

impl MarkdownHighlighter {
    pub fn highlight_line(&mut self, line: &str) -> Vec<(Class, String)> {
        let mut s = Scanner::new(line);
        if line.trim().is_empty() {
            if let Block::Fence(..) = self.block {
                s.emit_rest(Class::Plain);
                return s.out;
            }
            self.block = Block::Normal;
            s.emit_rest(Class::Plain);
            return s.out;
        }
        match self.block {
            Block::Fence(c, n) => {
                if let Some((fc, fnum)) = fence(line) {
                    if fc == c && fnum >= n && line.trim()[fnum..].trim().is_empty() {
                        self.block = Block::Normal;
                    }
                }
                s.emit_rest(Class::Plain);
                return s.out;
            }
            Block::Red => {
                self.inline(&mut s, Class::Variable);
                return s.out;
            }
            Block::Normal | Block::Paragraph => {}
        }
        if self.block == Block::Normal {
            if let Some((c, n)) = fence(line) {
                self.block = Block::Fence(c, n);
                let indent = leading_spaces(line);
                s.emit(indent + n, Class::Plain);
                let rest = s.rest_len();
                let lang: String = s.chars[s.pos..].iter().collect();
                let trimmed = lang.trim_start();
                let ws = lang.len() - trimmed.len();
                s.emit(ws, Class::Plain);
                let _ = rest;
                s.emit_rest(Class::Number);
                return s.out;
            }
            if leading_spaces(line) >= 4 {
                s.emit_rest(Class::Plain);
                return s.out;
            }
        }
        if let Some(level) = heading_level(line) {
            s.emit(level, Class::Function);
            while s.peek().is_some_and(|c| c == ' ' || c == '\t') {
                s.emit(1, Class::Plain);
            }
            self.inline(&mut s, Class::Function);
            self.block = Block::Normal;
            return s.out;
        }
        if is_list_item(line) || is_quote(line) {
            self.block = Block::Red;
            self.inline(&mut s, Class::Variable);
            return s.out;
        }
        if self.reference_definition(&mut s) {
            return s.out;
        }
        self.block = Block::Paragraph;
        self.inline(&mut s, Class::Plain);
        s.out
    }

    fn reference_definition(&mut self, s: &mut Scanner) -> bool {
        let line: String = s.chars.iter().collect();
        let indent = leading_spaces(&line);
        let rest = &line[indent..];
        if !rest.starts_with('[') {
            return false;
        }
        let close = match rest.find("]:") {
            Some(c) => c,
            None => return false,
        };
        if rest[1..close].contains(']') {
            return false;
        }
        let after = &rest[close + 2..];
        let url_start = after.len() - after.trim_start().len();
        let url_len = after[url_start..].find(|c: char| c.is_whitespace()).unwrap_or(after.len() - url_start);
        let total = indent + close + 2 + url_start + url_len;
        s.emit(indent, Class::Plain);
        s.emit(total - indent, Class::Number);
        while !s.eof() {
            let c = s.peek().unwrap();
            if c == '"' || c == '\'' || c == '(' {
                s.emit(1, Class::Plain);
                while s.peek().is_some_and(|d| d != c && !(c == '(' && d == ')')) {
                    s.emit(1, Class::Variable);
                }
                s.emit(1, Class::Plain);
            } else {
                s.emit(1, Class::Variable);
            }
        }
        true
    }

    fn inline(&mut self, s: &mut Scanner, base: Class) {
        while !s.eof() {
            let c = s.peek().unwrap();
            if c == '`' {
                let n = s.chars[s.pos..].iter().take_while(|x| **x == '`').count();
                // find the closing run of backticks
                let mut i = s.pos + n;
                let mut found = None;
                while i < s.chars.len() {
                    if s.chars[i] == '`' {
                        let m = s.chars[i..].iter().take_while(|x| **x == '`').count();
                        if m == n {
                            found = Some(i + m);
                            break;
                        }
                        i += m;
                    } else {
                        i += 1;
                    }
                }
                if let Some(end) = found {
                    let len = end - s.pos;
                    s.emit(len, Class::String);
                    continue;
                }
                s.emit(n, base);
                continue;
            }
            if (c == '*' || c == '_') && self.emphasis(s, base) {
                continue;
            }
            if c == '!' && s.peek_at(1) == Some('[') {
                if let Some(len) = link_len(s, s.pos + 1) {
                    s.emit(len + 1, Class::Number);
                    continue;
                }
            }
            if c == '[' {
                if let Some(len) = link_len(s, s.pos) {
                    s.emit(len, Class::Number);
                    continue;
                }
            }
            if c == '<' {
                let rest: String = s.chars[s.pos..].iter().collect();
                if let Some(end) = rest.find('>') {
                    let inner = &rest[1..end];
                    if (inner.starts_with("http://") || inner.starts_with("https://") || inner.starts_with("mailto:"))
                        && !inner.contains(' ')
                    {
                        let len = rest[..=end].chars().count();
                        s.emit(len, Class::Number);
                        continue;
                    }
                }
            }
            if c == '\\' && s.pos + 1 == s.chars.len() {
                s.emit(1, Class::Escape);
                continue;
            }
            if c == '\\' && s.peek_at(1).is_some_and(|d| "\\`*_{}[]()#+-.!<>&".contains(d)) {
                s.emit(2, Class::Escape);
                continue;
            }
            s.emit(1, base);
        }
    }

    fn emphasis(&mut self, s: &mut Scanner, base: Class) -> bool {
        let c = s.peek().unwrap();
        let n = s.chars[s.pos..].iter().take_while(|x| **x == c).count();
        if n > 2 {
            return false;
        }
        // intraword underscores are not emphasis
        if c == '_' && s.pos > 0 && s.chars[s.pos - 1].is_alphanumeric() {
            return false;
        }
        let start = s.pos + n;
        if start >= s.chars.len() || s.chars[start].is_whitespace() {
            return false;
        }
        let mut i = start;
        while i + n <= s.chars.len() {
            if s.chars[i..i + n].iter().all(|x| *x == c)
                && !s.chars[i - 1].is_whitespace()
                && (n == 2 || s.chars.get(i + 1) != Some(&c))
            {
                if c == '_' && s.chars.get(i + n).is_some_and(|x| x.is_alphanumeric()) {
                    i += 1;
                    continue;
                }
                let len = i + n - s.pos;
                let class = if n == 2 { Class::Type } else { Class::Keyword };
                s.emit(len, class);
                let _ = base;
                return true;
            }
            i += 1;
        }
        false
    }
}

/// Length of a `[text](url)` link starting at `start`.
fn link_len(s: &Scanner, start: usize) -> Option<usize> {
    let chars = &s.chars;
    let mut i = start + 1;
    let mut depth = 1;
    while i < chars.len() {
        match chars[i] {
            '[' => depth += 1,
            ']' => {
                depth -= 1;
                if depth == 0 {
                    break;
                }
            }
            _ => {}
        }
        i += 1;
    }
    if i >= chars.len() {
        return None;
    }
    let close = i;
    match chars.get(close + 1) {
        Some('(') => {
            let mut j = close + 2;
            while j < chars.len() && chars[j] != ')' {
                j += 1;
            }
            if j < chars.len() {
                Some(j + 1 - start)
            } else {
                None
            }
        }
        Some('[') => {
            let mut j = close + 2;
            while j < chars.len() && chars[j] != ']' {
                j += 1;
            }
            if j < chars.len() {
                Some(j + 1 - start)
            } else {
                None
            }
        }
        _ => None,
    }
}
