    "fgets", "fputs", "fputc", "fgetc", "getc", "putc", "puts", "putchar", "getchar", "fflush",
    "fseek", "ftell", "rewind", "feof", "ferror", "perror", "remove", "rename", "tmpfile",
    "exit", "abort", "atexit", "atoi", "atof", "atol", "strtol", "strtoul", "strtod", "qsort",
    "bsearch", "abs", "labs", "div", "rand", "srand", "time", "clock", "difftime", "mktime",
    "localtime", "gmtime", "strftime", "getenv", "system", "isalpha", "isdigit", "isalnum",
    "isspace", "isupper", "islower", "toupper", "tolower", "sqrt", "pow", "sin", "cos", "tan",
    "floor", "ceil", "fabs", "log", "exp", "assert", "setjmp", "longjmp", "signal", "raise",
];

#[derive(Default)]
pub struct CHighlighter {
    cpp: bool,
    comment: bool,
    params_depth: usize,
    paren_depth: usize,
}

impl CHighlighter {
    pub fn new(cpp: bool) -> Self {
        Self {
            cpp,
            ..Default::default()
        }
    }

    fn is_keyword(&self, word: &str) -> bool {
        C_KEYWORDS.contains(&word) || (self.cpp && CPP_KEYWORDS.contains(&word))
    }

    pub fn highlight_line(&mut self, line: &str) -> Vec<(Class, String)> {
        let mut s = Scanner::new(line);
        if !self.comment {
            let trimmed = line.trim_start();
            if trimmed.starts_with('#') {
                self.preprocessor(&mut s);
                return s.out;
            }
        }
        while !s.eof() {
            if self.comment {
                if s.starts_with("*/") {
                    s.emit(2, Class::Comment);
                    self.comment = false;
                } else {
                    s.emit(1, Class::Comment);
                }
                continue;
            }
            self.token(&mut s);
        }
        s.out
    }

    fn preprocessor(&mut self, s: &mut Scanner) {
        while s.peek().is_some_and(|c| c.is_whitespace()) {
            s.emit(1, Class::Plain);
        }
        let start = s.pos;
        s.pos += 1;
        while s.peek().is_some_and(|c| c == ' ') {
            s.pos += 1;
        }
        let len = s.ident_len();
        let directive = s.word_at(s.pos, len);
        s.pos += len;
        let n = s.pos - start;
        s.pos = start;
        s.emit(n, Class::Keyword);
        match directive.as_str() {
            "include" | "import" => {
                while !s.eof() {
                    let c = s.peek().unwrap();
                    if c == '<' {
                        s.emit(1, Class::Plain);
                        while s.peek().is_some_and(|c| c != '>') {
                            s.emit(1, Class::String);
                        }
                        s.emit(1, Class::Plain);
                    } else if c == '"' {
                        self.string(s, '"');
                    } else {
                        s.emit(1, Class::Plain);
                    }
                }
            }
            "define" => {
                while s.peek().is_some_and(|c| c == ' ') {
                    s.emit(1, Class::Plain);
                }
                let len = s.ident_len();
                if s.chars.get(s.pos + len) == Some(&'(') {
                    s.emit(len, Class::Function);
                    s.emit(1, Class::Plain);
                    while let Some(c) = s.peek() {
                        if c == ')' {
                            s.emit(1, Class::Plain);
                            break;
                        }
                        if is_ident_start(c) {
                            let l = s.ident_len();
                            s.emit(l, Class::Variable);
                        } else {
                            s.emit(1, Class::Plain);
                        }
                    }
                    s.emit_rest(Class::Plain);
                } else {
                    s.emit(len, Class::Plain);
                    self.expression(s);
                }
            }
            "if" | "elif" | "ifdef" | "ifndef" => {
                while !s.eof() {
                    let c = s.peek().unwrap();
                    if is_ident_start(c) {
                        let l = s.ident_len();
                        let w = s.word_at(s.pos, l);
                        s.emit(l, if w == "defined" { Class::Keyword } else { Class::Plain });
                    } else {
                        s.emit(1, Class::Plain);
                    }
                }
            }
            _ => self.expression(s),
        }
    }

    fn expression(&mut self, s: &mut Scanner) {
        while !s.eof() {
            if self.comment {
                if s.starts_with("*/") {
                    s.emit(2, Class::Comment);
                    self.comment = false;
                } else {
                    s.emit(1, Class::Comment);
                }
                continue;
            }
            self.token(s);
        }
    }

    fn escape_len(s: &Scanner) -> usize {
        if s.peek() != Some('\\') {
            return 0;
        }
        match s.peek_at(1) {
            Some('x') => {
                let mut i = 2;
                while s.peek_at(i).is_some_and(|c| c.is_ascii_hexdigit()) {
                    i += 1;
                }
                i
            }
            Some(c) if c.is_digit(8) => {
                let mut i = 1;
                while i < 4 && s.peek_at(i).is_some_and(|c| c.is_digit(8)) {
                    i += 1;
                }
                i
            }
            Some(_) => 2,
            None => 1,
        }
    }

    fn string(&mut self, s: &mut Scanner, quote: char) {
        s.emit(1, Class::Plain);
        while let Some(c) = s.peek() {
            if c == quote {
                s.emit(1, Class::Plain);
                return;
            }
            let n = Self::escape_len(s);
            if n > 0 {
                s.emit(n, Class::Escape);
                continue;
            }
            if c == '%' && quote == '"' {
                if let Some(n) = format_len(s) {
                    s.emit(n, Class::Number);
                    continue;
                }
            }
            s.emit(1, Class::String);
        }
    }

    fn token(&mut self, s: &mut Scanner) {
        let c = s.peek().unwrap();
        if c.is_whitespace() {
            s.emit(1, Class::Plain);
            return;
        }
        if s.starts_with("//") {
            s.emit_rest(Class::Comment);
            return;
        }
        if s.starts_with("/*") {
            s.emit(2, Class::Comment);
            self.comment = true;
            return;
        }
        if c == '"' || c == '\'' {
            self.string(s, c);
            return;
        }
        if (c.is_ascii_digit() || (c == '.' && s.peek_at(1).is_some_and(|c| c.is_ascii_digit())))
            && (s.pos == 0 || !is_ident_char(s.prev().unwrap()))
        {
            let mut i = 0;
            while s.peek_at(i).is_some_and(|c| c.is_ascii_alphanumeric() || c == '.' || c == '_')
                || (s.peek_at(i).is_some_and(|c| c == '+' || c == '-')
                    && i > 0
                    && s.peek_at(i - 1).is_some_and(|c| c == 'e' || c == 'E')
                    && !s.word_at(s.pos, i).starts_with("0x"))
            {
                i += 1;
            }
            s.emit(i, Class::Number);
            return;
        }
        if is_ident_start(c) {
            self.identifier(s);
            return;
        }
        match c {
            '(' => self.paren_depth += 1,
            ')' => {
                if self.params_depth == self.paren_depth {
                    self.params_depth = 0;
                }
                self.paren_depth = self.paren_depth.saturating_sub(1);
            }
            _ => {}
        }
        s.emit(1, Class::Plain);
    }

    fn identifier(&mut self, s: &mut Scanner) {
        let start = s.pos;
        let mut len = s.ident_len();
        // qualified names in C++
        if self.cpp {
            let mut end = start + len;
            while s.chars.get(end) == Some(&':') && s.chars.get(end + 1) == Some(&':') && s.chars.get(end + 2).is_some_and(|c| is_ident_start(*c)) {
                end += 2;
                while end < s.chars.len() && is_ident_char(s.chars[end]) {
                    end += 1;
                }
            }
            if end != start + len && s.chars.get(end) == Some(&'(') {
                len = end - start;
                s.emit(len, Class::Function);
                return;
            }
        }
        let word = s.word_at(start, len);
        let after = start + len;
        let next = s.chars.get(after).copied();
        let prev = s.prev_non_ws(start);
        let member = start > 0
            && (s.chars[start - 1] == '.'
                || (start > 1 && s.chars[start - 1] == '>' && s.chars[start - 2] == '-'));

        if self.params_depth > 0 && self.paren_depth >= self.params_depth {
            if self.is_keyword(&word) {
                s.emit(len, Class::Keyword);
                return;
            }
            let next_ws = s.next_non_ws(after).map(|(_, c)| c);
            if matches!(next_ws, Some(',') | Some(')') | Some('[') | Some('=')) {
                s.emit(len, Class::Variable);
                return;
            }
            s.emit(len, Class::Plain);
            return;
        }
        if self.is_keyword(&word) {
            s.emit(len, Class::Keyword);
            return;
        }
        if CONSTANTS.contains(&word.as_str()) || (self.cpp && word == "nullptr") {
            s.emit(len, Class::Number);
            return;
        }
        if self.cpp && word == "this" {
            s.emit(len, Class::Variable);
            return;
        }
        if next == Some('(') {
            if LIBRARY_FUNCTIONS.contains(&word.as_str()) && !member {
                s.emit(len, Class::Support);
                return;
            }
            // function definitions and declarations
            let declaration = match prev {
                Some((_, c)) => c == '*' || c == '&' || is_ident_char(c) || c == '>',
                None => false,
            } && !matches!(self.previous_word(s, start).as_str(), "return" | "else" | "case" | "new" | "delete" | "sizeof");
            s.emit(len, Class::Function);
            if declaration && !member && word != "sizeof" {
                self.paren_depth += 1;
                self.params_depth = self.paren_depth;
                s.emit(1, Class::Plain);
            }
            return;
        }
        if word == "sizeof" {
            s.emit(len, Class::Plain);
            return;
        }
        if member {
            let arrow = s.chars[start - 1] == '>';
            if arrow && !self.cpp {
                s.emit(len, Class::Plain);
            } else {
                s.emit(len, Class::Variable);
            }
            return;
        }
        s.emit(len, Class::Plain);
    }

    fn previous_word(&self, s: &Scanner, start: usize) -> String {
        let mut i = start;
        while i > 0 && s.chars[i - 1].is_whitespace() {
            i -= 1;
        }
        let end = i;
        while i > 0 && is_ident_char(s.chars[i - 1]) {
            i -= 1;
        }
        s.chars[i..end].iter().collect()
    }
}

fn format_len(s: &Scanner) -> Option<usize> {
    if s.peek_at(1) == Some('%') {
        return Some(2);
    }
    let mut i = 1;
    while s.peek_at(i).is_some_and(|c| "-+ #0".contains(c)) {
        i += 1;
    }
    while s.peek_at(i).is_some_and(|c| c.is_ascii_digit() || c == '*') {
        i += 1;
    }
    if s.peek_at(i) == Some('.') {
        i += 1;
        while s.peek_at(i).is_some_and(|c| c.is_ascii_digit() || c == '*') {
            i += 1;
        }
    }
    while s.peek_at(i).is_some_and(|c| "hlLqjzt".contains(c)) {
        i += 1;
    }
    if s.peek_at(i).is_some_and(|c| "diouxXeEfFgGaAcspn".contains(c)) {
        Some(i + 1)
    } else {
        None
    }
}
