static void count_stream(FILE *stream, counts_t *counts)
{
    char buffer[BUFFER_SIZE];
    int in_word = 0;
    size_t n;

    while ((n = fread(buffer, 1, sizeof buffer, stream)) > 0) {
        for (size_t i = 0; i < n; i++) {
            unsigned char c = (unsigned char)buffer[i];
            counts->chars++;
            if (c == '\n')
                counts->lines++;
            if (isspace(c)) {
                in_word = 0;
            } else if (!in_word) {
                in_word = 1;
                counts->words++;
            }
        }
    }
}

int main(int argc, char *argv[])
{
    counts_t total = {0, 0, 0};
    if (argc < 2) {
        count_stream(stdin, &total);
    } else {
        for (int i = 1; i < argc; i++) {
            FILE *f = fopen(argv[i], "r");
            if (f == NULL) {
                perror(argv[i]);
                return EXIT_FAILURE;
            }
            count_stream(f, &total);
            fclose(f);
        }
    }
    printf("%zu %zu %zu\n", total.lines, total.words, total.chars);
    return EXIT_SUCCESS;
}
