//! Highlighting of Go source files.

use super::scanner::{is_ident_char, is_ident_start, Class, Scanner};

const KEYWORDS: &[&str] = &[
    "break", "case", "chan", "const", "continue", "default", "defer", "else", "fallthrough",
    "for", "func", "go", "goto", "if", "import", "interface", "map", "package", "range",
    "return", "select", "struct", "switch", "type", "var",
];

const TYPES: &[&str] = &[
    "bool", "byte", "complex64", "complex128", "error", "float32", "float64", "int", "int8",
    "int16", "int32", "int64", "rune", "string", "uint", "uint8", "uint16", "uint32", "uint64",
    "uintptr", "any",
];

const CONSTANTS: &[&str] = &["true", "false", "nil", "iota"];

const BUILTINS: &[&str] = &[
    "append", "cap", "close", "complex", "copy", "delete", "imag", "len", "make", "new",
    "panic", "print", "println", "real", "recover",
];

#[derive(Default)]
pub struct GoHighlighter {
    comment: bool,
    raw_string: bool,
    struct_depth: usize,
    expect_struct_body: bool,
    brace_depth: usize,
    /// 0: none, 1: expecting receiver or name, 2: name seen expecting params
    func_state: u8,
    params_depth: usize,
    paren_depth: usize,
    receiver_depth: usize,
    var_block: bool,
    expect_var_name: bool,
}

impl GoHighlighter {
    pub fn highlight_line(&mut self, line: &str) -> Vec<(Class, String)> {
        let mut s = Scanner::new(line);
        let mut first = true;
        while !s.eof() {
            if self.comment {
                if s.starts_with("*/") {
                    s.emit(2, Class::Comment);
                    self.comment = false;
                } else {
                    s.emit(1, Class::Comment);
                }
                continue;
            }
            if self.raw_string {
                if s.peek() == Some('`') {
                    s.emit(1, Class::Plain);
                    self.raw_string = false;
                } else {
                    s.emit(1, Class::String);
                }
                continue;
            }
            let c = s.peek().unwrap();
            if c.is_whitespace() {
                s.emit(1, Class::Plain);
                continue;
            }
            self.token(&mut s, first);
            first = false;
        }
        self.expect_var_name = false;
        s.out
    }

    fn escape_len(s: &Scanner) -> usize {
        if s.peek() != Some('\\') {
            return 0;
        }
        match s.peek_at(1) {
            Some('x') => 4,
            Some('u') => 6,
            Some('U') => 10,
            Some(c) if c.is_digit(8) => 4,
            Some(_) => 2,
            None => 1,
        }
    }

    fn string(&mut self, s: &mut Scanner, quote: char) {
        s.emit(1, Class::Plain);
        while let Some(c) = s.peek() {
            if c == quote {
                s.emit(1, Class::Plain);
                return;
            }
            let n = Self::escape_len(s);
            if n > 0 {
                s.emit(n, Class::Escape);
                continue;
            }
            if c == '%' && quote == '"' {
                if let Some(n) = verb_len(s) {
                    s.emit(n, Class::Number);
                    continue;
                }
            }
            s.emit(1, Class::String);
        }
    }

    fn token(&mut self, s: &mut Scanner, first: bool) {
        let c = s.peek().unwrap();
        if s.starts_with("//") {
            s.emit_rest(Class::Comment);
            return;
        }
        if s.starts_with("/*") {
            s.emit(2, Class::Comment);
            self.comment = true;
            return;
        }
        if c == '"' || c == '\'' {
            self.string(s, c);
            return;
        }
        if c == '`' {
            s.emit(1, Class::Plain);
            self.raw_string = true;
            return;
        }
        if (c.is_ascii_digit() || (c == '.' && s.peek_at(1).is_some_and(|c| c.is_ascii_digit())))
            && (s.pos == 0 || !is_ident_char(s.prev().unwrap()))
        {
            let mut i = 0;
            while s.peek_at(i).is_some_and(|c| c.is_ascii_alphanumeric() || c == '.' || c == '_') {
                i += 1;
            }
            s.emit(i, Class::Number);
            return;
        }
        if is_ident_start(c) {
            self.identifier(s, first);
            return;
        }
        match c {
            '(' => {
                self.paren_depth += 1;
                if self.func_state == 1 {
                    // receiver
                    self.receiver_depth = self.paren_depth;
                } else if self.func_state == 2 {
                    self.params_depth = self.paren_depth;
                    self.func_state = 0;
                }
                if self.var_block_start(s) {
                    self.var_block = true;
                }
            }
            ')' => {
                if self.receiver_depth == self.paren_depth {
                    self.receiver_depth = 0;
                }
                if self.params_depth == self.paren_depth {
                    self.params_depth = 0;
                }
                self.paren_depth = self.paren_depth.saturating_sub(1);
                if self.var_block && self.paren_depth == 0 {
                    self.var_block = false;
                }
            }
            '{' => {
                self.brace_depth += 1;
                if self.expect_struct_body {
                    self.expect_struct_body = false;
                    self.struct_depth = self.brace_depth;
                }
                self.func_state = 0;
            }
            '}' => {
                if self.struct_depth == self.brace_depth {
                    self.struct_depth = 0;
                }
                self.brace_depth = self.brace_depth.saturating_sub(1);
            }
            _ => {}
        }
        s.emit(1, Class::Plain);
    }

    fn var_block_start(&self, s: &Scanner) -> bool {
        let before: String = s.chars[..s.pos].iter().collect();
        before.trim() == "var"
    }

    fn short_declaration(&self, s: &Scanner, start: usize) -> bool {
        // ident (, ident)* :=
        let mut i = start;
        loop {
            while i < s.chars.len() && is_ident_char(s.chars[i]) {
                i += 1;
            }
            while i < s.chars.len() && s.chars[i] == ' ' {
                i += 1;
            }
            match s.chars.get(i) {
                Some(',') => {
                    i += 1;
                    while i < s.chars.len() && s.chars[i] == ' ' {
                        i += 1;
                    }
                    if !s.chars.get(i).is_some_and(|c| is_ident_start(*c)) {
                        return false;
                    }
                }
                Some(':') => return s.chars.get(i + 1) == Some(&'='),
                _ => return false,
            }
        }
    }

    fn identifier(&mut self, s: &mut Scanner, first: bool) {
        let start = s.pos;
        let len = s.ident_len();
        let word = s.word_at(start, len);
        let after = start + len;
        let next = s.chars.get(after).copied();
        let member = start > 0 && s.chars[start - 1] == '.';
        let prev = s.prev_non_ws(start).map(|(_, c)| c);

        if member {
            if next == Some('(') {
                s.emit(len, Class::Function);
            } else {
                s.emit(len, Class::Variable);
            }
            return;
        }
        if self.receiver_depth > 0 {
            let class = if TYPES.contains(&word.as_str()) {
                Class::Keyword
            } else if prev == Some('(') {
                Class::Variable
            } else {
                Class::Plain
            };
            s.emit(len, class);
            return;
        }
        if self.params_depth > 0 && self.paren_depth >= self.params_depth {
            if TYPES.contains(&word.as_str()) || KEYWORDS.contains(&word.as_str()) {
                s.emit(len, Class::Keyword);
                return;
            }
            let is_name = matches!(prev, Some('(') | Some(','));
            let next_ws = s.next_non_ws(after);
            let followed_by_type = match next_ws {
                Some((_, ',')) => true,
                Some((_, ')')) => false,
                Some((i, c)) => i > after && (is_ident_start(c) || c == '*' || c == '[' || c == '.'),
                None => false,
            };
            if is_name && followed_by_type {
                s.emit(len, Class::Variable);
            } else {
                s.emit(len, Class::Plain);
            }
            return;
        }
        if self.func_state == 1 {
            // name of the function
            s.emit(len, Class::Function);
            self.func_state = 2;
            return;
        }
        if KEYWORDS.contains(&word.as_str()) {
            match word.as_str() {
                "func" => {
                    // function declarations start at the beginning of a line
                    self.func_state = if first { 1 } else { 0 };
                }
                "struct" => self.expect_struct_body = true,
                "var" => self.expect_var_name = true,
                _ => {}
            }
            s.emit(len, Class::Keyword);
            return;
        }
        if TYPES.contains(&word.as_str()) {
            s.emit(len, Class::Keyword);
            return;
        }
        if CONSTANTS.contains(&word.as_str()) {
            s.emit(len, Class::Number);
            return;
        }
        if self.expect_var_name || (self.var_block && first) {
            self.expect_var_name = false;
            s.emit(len, Class::Variable);
            return;
        }
        if self.short_declaration(s, start) {
            s.emit(len, Class::Variable);
            return;
        }
        if next == Some('(') {
            let class = if BUILTINS.contains(&word.as_str()) {
                Class::Support
            } else {
                Class::Function
            };
            // interface methods
            s.emit(len, class);
            return;
        }
        if self.struct_depth > 0 && self.brace_depth == self.struct_depth && (first || prev == Some(',')) {
            s.emit(len, Class::Variable);
            return;
        }
        s.emit(len, Class::Plain);
    }
}

fn verb_len(s: &Scanner) -> Option<usize> {
    if s.peek_at(1) == Some('%') {
        return Some(2);
    }
    let mut i = 1;
    while s.peek_at(i).is_some_and(|c| "+-# 0".contains(c)) {
        i += 1;
    }
    while s.peek_at(i).is_some_and(|c| c.is_ascii_digit() || c == '.' || c == '*') {
        i += 1;
    }
    if s.peek_at(i).is_some_and(|c| "vTtbcdoqxXUeEfFgGsp".contains(c)) {
        Some(i + 1)
    } else {
        None
    }
}
