//! Highlighting of shell scripts.

use super::scanner::{Class, Scanner};

const KEYWORDS: &[&str] = &[
    "if", "then", "elif", "else", "fi", "for", "in", "do", "done", "while", "until", "case",
    "esac", "function", "select", "time", "coproc",
];

const DECLARATIONS: &[&str] = &["local", "readonly", "export", "declare", "typeset"];

const BUILTINS: &[&str] = &[
    "echo", "printf", "read", "exit", "cd", "source", ".", ":", "set", "alias", "unalias",
    "trap", "kill", "wait", "shift", "eval", "exec", "unset", "let", "pwd", "pushd", "popd",
    "dirs", "bg", "fg", "jobs", "disown", "umask", "ulimit", "type", "hash", "help", "history",
    "getopts", "shopt", "enable", "builtin", "command", "caller", "compgen", "complete",
    "logout", "mapfile", "readarray", "suspend", "times", "break", "continue", "return",
    "[", "[[",
];

#[derive(Clone, Copy, PartialEq, Eq)]
enum Ctx {
    /// Inside of a double quoted string
    Double,
    /// Inside of a command substitution $( ... )
    Subst,
    /// Inside of an arithmetic expansion $(( ... ))
    Arith,
    /// Inside of backticks
    Backtick,
}

#[derive(Default)]
pub struct ShellHighlighter {
    ctx: Vec<Ctx>,
    single_quote: bool,
    heredoc: Option<String>,
    pending_heredoc: Option<String>,
    command_position: bool,
    /// The current command is a regular command (options are highlighted).
    after_command: bool,
    after_builtin_test: bool,
    after_declaration: bool,
    case_pattern: bool,
    line_start: bool,
}

impl ShellHighlighter {
    fn base(&self) -> Class {
        match self.ctx.last() {
            Some(Ctx::Double) | Some(Ctx::Subst) | Some(Ctx::Arith) | Some(Ctx::Backtick) => Class::String,
            None => Class::Plain,
        }
    }

    pub fn highlight_line(&mut self, line: &str) -> Vec<(Class, String)> {
        let mut s = Scanner::new(line);
        if let Some(end) = self.heredoc.clone() {
            if line.trim() == end {
                s.emit_rest(Class::Keyword);
                self.heredoc = None;
            } else {
                while !s.eof() {
                    if s.peek() == Some('$') {
                        self.dollar(&mut s);
                    } else {
                        s.emit(1, Class::String);
                    }
                }
            }
            return s.out;
        }
        if self.ctx.is_empty() && !self.single_quote {
            self.command_position = true;
            self.after_command = false;
            self.after_builtin_test = false;
            self.after_declaration = false;
        }
        self.line_start = true;
        while !s.eof() {
            if self.single_quote {
                if s.peek() == Some('\'') {
                    s.emit(1, Class::Plain);
                    self.single_quote = false;
                } else {
                    s.emit(1, Class::String);
                }
                continue;
            }
            self.token(&mut s);
        }
        if let Some(end) = self.pending_heredoc.take() {
            self.heredoc = Some(end);
        }
        s.out
    }

    fn token(&mut self, s: &mut Scanner) {
        let c = s.peek().unwrap();
        let base = self.base();
        let in_double = self.ctx.last() == Some(&Ctx::Double);
        if in_double {
            match c {
                '"' => {
                    s.emit(1, Class::Plain);
                    self.ctx.pop();
                }
                '\\' => {
                    if s.peek_at(1).is_some_and(|c| "$`\"\\\n".contains(c)) {
                        s.emit(2, Class::Escape);
                    } else {
                        s.emit(1, Class::String);
                    }
                }
                '$' => self.dollar(s),
                '`' => {
                    s.emit(1, Class::String);
                    self.ctx.push(Ctx::Backtick);
                    self.command_position = true;
                }
                _ => s.emit(1, Class::String),
            }
            return;
        }
        if c.is_whitespace() {
            s.emit(1, base);
            return;
        }
        if c == '#' && (s.pos == 0 || s.prev().is_some_and(|p| p.is_whitespace())) && self.ctx.is_empty() {
            s.emit_rest(Class::Comment);
            return;
        }
        match c {
            '"' => {
                s.emit(1, Class::Plain);
                self.ctx.push(Ctx::Double);
                self.command_position = false;
                return;
            }
            '\'' => {
                s.emit(1, Class::Plain);
                self.single_quote = true;
                self.command_position = false;
                return;
            }
            '$' => {
                self.dollar(s);
                self.command_position = false;
                return;
            }
            '`' => {
                if self.ctx.last() == Some(&Ctx::Backtick) {
                    s.emit(1, Class::String);
                    self.ctx.pop();
                } else {
                    s.emit(1, Class::String);
                    self.ctx.push(Ctx::Backtick);
                    self.command_position = true;
                }
                return;
            }
            '\\' => {
                s.emit(2, base);
                return;
            }
            _ => {}
        }
        if self.ctx.last() == Some(&Ctx::Arith) {
            if s.starts_with("))") {
                s.emit(2, Class::String);
                self.ctx.pop();
                return;
            }
            if c.is_ascii_digit() {
                let n = s.chars[s.pos..].iter().take_while(|c| c.is_ascii_alphanumeric()).count();
                s.emit(n, Class::Number);
                return;
            }
            if "+-*/%<>=!&|^~?:".contains(c) {
                s.emit(1, Class::Plain);
                return;
            }
            s.emit(1, Class::String);
            return;
        }
        if c == ')' && self.ctx.last() == Some(&Ctx::Subst) {
            s.emit(1, Class::String);
            self.ctx.pop();
            return;
        }
        if c == ')' && self.case_pattern {
            s.emit(1, Class::Keyword);
            self.case_pattern = false;
            self.command_position = true;
            return;
        }
        if c == '|' || c == '&' || c == ';' || c == '(' || c == '{' || c == '}' {
            let n = if s.peek_at(1) == Some(c) { 2 } else { 1 };
            if c == '&' && s.prev() == Some('>') {
                s.emit(1, Class::Plain);
                return;
            }
            s.emit(n, Class::Plain);
            if c == ';' && n == 2 {
                // end of a case branch
                self.case_pattern = true;
            }
            self.command_position = true;
            self.after_command = false;
            self.after_builtin_test = false;
            self.after_declaration = false;
            return;
        }
        if c.is_ascii_digit() && s.peek_at(1) == Some('>') && s.prev().is_none_or(|p| p.is_whitespace()) {
            s.emit(1, Class::Number);
            return;
        }
        if c == '>' || c == '<' {
            if s.starts_with("<<") && !s.starts_with("<<<") {
                s.emit(2, Class::Plain);
                let mut i = 0;
                if s.peek() == Some('-') {
                    i = 1;
                }
                let start = s.pos + i;
                let mut j = start;
                while j < s.chars.len() && !s.chars[j].is_whitespace() && s.chars[j] != ';' {
                    j += 1;
                }
                let word: String = s.chars[start..j].iter().collect();
                let word = word.trim_matches(|c| c == '\'' || c == '"').to_string();
                s.emit(j - s.pos, Class::Keyword);
                self.pending_heredoc = Some(word);
                return;
            }
            s.emit(1, Class::Plain);
            if s.peek() == Some('&') {
                s.emit(1, Class::Plain);
                if s.peek().is_some_and(|c| c.is_ascii_digit()) {
                    s.emit(1, Class::Number);
                }
            }
            self.command_position = false;
            return;
        }
        // words
        let start = s.pos;
        let mut end = start;
        while end < s.chars.len() {
            let ch = s.chars[end];
            if ch.is_whitespace() || "|&;()<>\"'`$".contains(ch) {
                break;
            }
            if ch == '=' && end > start {
                break;
            }
            end += 1;
        }
        if end == start {
            s.emit(1, base);
            return;
        }
        let word: String = s.chars[start..end].iter().collect();
        let next = s.chars.get(end).copied();

        // assignments
        if next == Some('=') && self.command_position && is_name(&word) {
            s.emit(end - start, Class::Variable);
            s.emit(1, Class::Plain);
            self.assignment_value(s);
            return;
        }
        if self.after_declaration && is_name(&word) {
            s.emit(end - start, Class::Variable);
            if s.peek() == Some('=') {
                s.emit(1, Class::Plain);
                self.assignment_value(s);
            }
            return;
        }
        if word.starts_with('-') && word.len() > 1 && (self.after_command || self.after_builtin_test || self.after_declaration) {
            if self.after_command && s.prev().is_some_and(|p| p == ' ') {
                // the whitespace before the option is part of the option
                let last = s.out.last_mut();
                if let Some(last) = last {
                    if last.0 == Class::Plain && last.1.ends_with(' ') {
                        last.1.pop();
                        if last.1.is_empty() {
                            s.out.pop();
                        }
                        s.push(Class::Variable, " ");
                    }
                }
            }
            s.emit(end - start, Class::Variable);
            return;
        }
        if self.command_position {
            self.command_position = false;
            if KEYWORDS.contains(&word.as_str()) && self.ctx.is_empty() {
                s.emit(end - start, Class::Keyword);
                match word.as_str() {
                    "if" | "then" | "elif" | "else" | "do" | "while" | "until" | "time" => self.command_position = true,
                    "function" => {
                        while s.peek() == Some(' ') {
                            s.emit(1, Class::Plain);
                        }
                        let n = s.chars[s.pos..].iter().take_while(|c| !c.is_whitespace() && **c != '(').count();
                        s.emit(n, Class::Function);
                    }
                    "case" => {}
                    _ => {}
                }
                return;
            }
            if DECLARATIONS.contains(&word.as_str()) || word == "return" {
                s.emit(end - start, Class::Keyword);
                if word != "return" {
                    self.after_declaration = true;
                }
                return;
            }
            if BUILTINS.contains(&word.as_str()) {
                s.emit(end - start, Class::Support);
                if word == "[" || word == "[[" || word == "read" {
                    self.after_builtin_test = true;
                }
                if word == "alias" {
                    while s.peek() == Some(' ') {
                        s.emit(1, Class::Plain);
                    }
                    let n = s.chars[s.pos..].iter().take_while(|c| **c != '=' && !c.is_whitespace()).count();
                    s.emit(n, Class::Function);
                }
                if word == "let" {
                    self.let_expression(s);
                }
                return;
            }
            // function definitions: name() {
            if s.chars.get(end) == Some(&'(') && s.chars.get(end + 1) == Some(&')') {
                s.emit(end - start, Class::Function);
                return;
            }
            s.emit(end - start, Class::Function);
            self.after_command = true;
            return;
        }
        if word == "]" || word == "]]" {
            s.emit(end - start, Class::Support);
            self.after_builtin_test = false;
            return;
        }
        if word == "in" && self.ctx.is_empty() && self.previous_keyword_for_or_case(s) {
            s.emit(end - start, Class::Keyword);
            if self.previous_word_is_case(s) {
                self.case_pattern = true;
            }
            return;
        }
        if (word == "then" || word == "do" || word == "fi" || word == "done" || word == "esac") && self.ctx.is_empty() {
            s.emit(end - start, Class::Keyword);
            self.command_position = true;
            return;
        }
        s.emit(end - start, base);
    }

    fn previous_keyword_for_or_case(&self, s: &Scanner) -> bool {
        let line: String = s.chars.iter().collect();
        let t = line.trim_start();
        t.starts_with("for ") || t.starts_with("case ") || t.starts_with("select ")
    }

    fn previous_word_is_case(&self, s: &Scanner) -> bool {
        let line: String = s.chars.iter().collect();
        line.trim_start().starts_with("case ")
    }

    fn let_expression(&mut self, s: &mut Scanner) {
        while let Some(c) = s.peek() {
            if c == ';' || c == '|' || c == '&' {
                break;
            }
            if c.is_ascii_digit() {
                let n = s.chars[s.pos..].iter().take_while(|c| c.is_ascii_alphanumeric()).count();
                s.emit(n, Class::Number);
            } else {
                s.emit(1, Class::Plain);
            }
        }
    }

    fn assignment_value(&mut self, s: &mut Scanner) {
        // unquoted values are strings, quoted values are handled by the tokenizer
        match s.peek() {
            Some('"') | Some('\'') | Some('$') | Some('`') | None => {}
            Some('(') => {
                // arrays
                let mut depth = 0;
                while let Some(c) = s.peek() {
                    s.emit(1, Class::Plain);
                    if c == '(' {
                        depth += 1;
                    } else if c == ')' {
                        depth -= 1;
                        if depth == 0 {
                            break;
                        }
                    }
                }
            }
            Some(_) => {
                while let Some(c) = s.peek() {
                    if c.is_whitespace() || "|&;()<>\"'`$".contains(c) {
                        break;
                    }
                    s.emit(1, Class::String);
                }
            }
        }
        self.command_position = true;
    }

    fn dollar(&mut self, s: &mut Scanner) {
        let quoted = self.ctx.last() == Some(&Ctx::Double);
        match s.peek_at(1) {
            Some('(') => {
                if s.peek_at(2) == Some('(') {
                    s.emit(1, Class::Plain);
                    s.emit(2, Class::String);
                    self.ctx.push(Ctx::Arith);
                } else {
                    s.emit(1, Class::Plain);
                    s.emit(1, Class::String);
                    self.ctx.push(Ctx::Subst);
                    self.command_position = true;
                }
            }
            Some('{') => {
                s.emit(1, Class::Plain);
                if quoted {
                    s.emit(1, Class::String);
                } else {
                    s.emit(1, Class::Plain);
                }
                if s.peek() == Some('#') || s.peek() == Some('!') {
                    s.emit(1, Class::Plain);
                }
                let n = s.chars[s.pos..]
                    .iter()
                    .take_while(|c| c.is_alphanumeric() || **c == '_' || **c == '@' || **c == '*' || **c == '[' || **c == ']')
                    .count();
                s.emit(n.max(0), Class::Variable);
                // the rest of the expansion
                while let Some(c) = s.peek() {
                    if c == '}' {
                        s.emit(1, if quoted { Class::String } else { Class::Plain });
                        break;
                    }
                    if quoted {
                        if c == '/' || c == '%' || c == '#' || c == ':' {
                            s.emit(1, Class::Plain);
                        } else {
                            s.emit(1, Class::String);
                        }
                    } else {
                        s.emit(1, Class::Plain);
                    }
                }
            }
            Some(c) if c.is_alphanumeric() || c == '_' => {
                s.emit(1, Class::Plain);
                let n = if c.is_ascii_digit() {
                    1
                } else {
                    s.chars[s.pos..].iter().take_while(|c| c.is_alphanumeric() || **c == '_').count()
                };
                s.emit(n, Class::Variable);
            }
            Some(c) if "@#?$!*-".contains(c) => {
                s.emit(1, Class::Plain);
                s.emit(1, Class::Variable);
            }
            _ => {
                let base = self.base();
                s.emit(1, base);
            }
        }
    }
}

fn is_name(word: &str) -> bool {
    let mut chars = word.chars();
    match chars.next() {
        Some(c) if c.is_alphabetic() || c == '_' => {}
        _ => return false,
    }
    word.chars().all(|c| c.is_alphanumeric() || c == '_' || c == '[' || c == ']')
}
