{"command":"cd /workspace && cat > src/ui/highlight/yaml.rs <<'EOF'
//! Highlighting of YAML files.

use super::scanner::{Class, Scanner};

const CONSTANTS: &[&str] = &[
    "true", "false", "True", "False", "TRUE", "FALSE", "null", "Null", "NULL", "~", "yes", "no",
    "Yes", "No", "YES", "NO", "on", "off", "On", "Off", "ON", "OFF", "y", "n", "Y", "N",
];

#[derive(Default)]
pub struct YamlHighlighter {
    /// Indentation of the key owning a block scalar.
    block_scalar: Option<usize>,
}

fn indentation(line: &str) -> usize {
    line.chars().take_while(|c| *c == ' ').count()
}

fn is_number(s: &str) -> bool {
    let t = s.trim_start_matches(['-', '+']);
    if t.is_empty() {
        return false;
    }
    if t.starts_with("0x") && t.len() > 2 && t[2..].chars().all(|c| c.is_ascii_hexdigit()) {
        return true;
    }
    if matches!(t, ".inf" | ".Inf" | ".INF" | ".nan" | ".NaN" | ".NAN") {
        return true;
    }
    let first = t.chars().next().unwrap();
    if !first.is_ascii_digit() {
        return false;
    }
    t.chars().all(|c| c.is_ascii_digit() || c == '.' || c == '_' || c == ':' || c == '-' || c == 'e' || c == 'E' || c == '+')
        && !t.ends_with('-')
}

impl YamlHighlighter {
    pub fn highlight_line(&mut self, line: &str) -> Vec<(Class, String)> {
        let mut s = Scanner::new(line);
        if let Some(indent) = self.block_scalar {
            if line.trim().is_empty() || indentation(line) > indent {
                s.emit_rest(Class::String);
                return s.out;
            }
            self.block_scalar = None;
        }
        let indent = indentation(line);
        s.emit(indent, Class::Plain);
        if s.starts_with("---") || s.starts_with("...") {
            s.emit_rest(Class::Plain);
            return s.out;
        }
        self.node(&mut s, indent);
        s.out
    }

    fn node(&mut self, s: &mut Scanner, indent: usize) {
        loop {
            while s.peek() == Some(' ') {
                s.emit(1, Class::Plain);
            }
            match s.peek() {
                None => return,
                Some('#') => {
                    s.emit_rest(Class::Comment);
                    return;
                }
                Some('-') if matches!(s.peek_at(1), Some(' ') | None) => {
                    s.emit(1, Class::Plain);
                    continue;
                }
                Some('?') | Some(':') if matches!(s.peek_at(1), Some(' ') | None) => {
                    s.emit(1, Class::Plain);
                    continue;
                }
                _ => {}
            }
            // key?
            if let Some(key_len) = self.key_len(s) {
                let c = s.peek().unwrap();
                if c == '"' || c == '\'' {
                    self.quoted(s, c);
                } else if s.starts_with("<<") {
                    s.emit(key_len, Class::Number);
                } else {
                    s.emit(key_len, Class::Variable);
                }
                s.emit(1, Class::Plain);
                continue;
            }
            self.value(s, indent);
            return;
        }
    }

    /// Length of a mapping key at the current position (excluding the colon).
    fn key_len(&self, s: &Scanner) -> Option<usize> {
        let c = s.peek()?;
        if c == '"' || c == '\'' {
            let mut i = 1;
            while let Some(d) = s.peek_at(i) {
                if d == '\\' && c == '"' {
                    i += 2;
                    continue;
                }
                if d == c {
                    break;
                }
                i += 1;
            }
            if s.peek_at(i) == Some(c) && s.peek_at(i + 1) == Some(':') && matches!(s.peek_at(i + 2), Some(' ') | None) {
                return Some(i + 1);
            }
            return None;
        }
        if "[]{},&*!|>%@`#".contains(c) {
            return None;
        }
        let mut i = 0;
        while let Some(d) = s.peek_at(i) {
            if d == ':' && matches!(s.peek_at(i + 1), Some(' ') | None) {
                return Some(i);
            }
            if d == '#' && i > 0 && s.peek_at(i - 1) == Some(' ') {
                return None;
            }
            i += 1;
        }
        None
    }

    fn quoted(&mut self, s: &mut Scanner, q: char) {
        s.emit(1, Class::Plain);
        while let Some(c) = s.peek() {
            if c == q {
                if q == '\'' && s.peek_at(1) == Some('\'') {
                    s.emit(2, Class::Escape);
                    continue;
                }
                s.emit(1, Class::Plain);
                return;
            }
            if c == '\\' && q == '"' {
                let n = match s.peek_at(1) {
                    Some('x') => 4,
                    Some('u') => 6,
                    Some('U') => 10,
                    Some(_) => 2,
                    None => 1,
                };
                s.emit(n, Class::Escape);
                continue;
            }
            s.emit(1, Class::String);
        }
    }

    fn value(&mut self, s: &mut Scanner, indent: usize) {
        let c = s.peek().unwrap();
        match c {
            '"' | '\'' => {
                self.quoted(s, c);
                self.trailing(s);
            }
            '|' | '>' => {
                s.emit(1, Class::Keyword);
                while s.peek().is_some_and(|c| "+-0123456789".contains(c)) {
                    s.emit(1, Class::Keyword);
                }
                self.trailing(s);
                self.block_scalar = Some(indent);
            }
            '&' => {
                s.emit(1, Class::Keyword);
                while s.peek().is_some_and(|c| !c.is_whitespace()) {
                    s.emit(1, Class::Plain);
                }
                self.node(s, indent);
            }
            '*' => {
                s.emit(1, Class::Keyword);
                while s.peek().is_some_and(|c| !c.is_whitespace() && c != ',' && c != ']' && c != '}') {
                    s.emit(1, Class::Variable);
                }
                self.trailing(s);
            }
            '[' | '{' => self.flow(s),
            _ => {
                let rest: String = s.chars[s.pos..].iter().collect();
                let end = rest.find(" #").unwrap_or(rest.len());
                let scalar = rest[..end].trim_end();
                let n = scalar.chars().count();
                let class = if is_number(scalar) || CONSTANTS.contains(&scalar) {
                    Class::Number
                } else {
                    Class::String
                };
                s.emit(n, class);
                self.trailing(s);
            }
        }
    }

    fn trailing(&mut self, s: &mut Scanner) {
        while let Some(c) = s.peek() {
            if c == '#' {
                s.emit_rest(Class::Comment);
                return;
            }
            s.emit(1, Class::Plain);
        }
    }

    fn flow(&mut self, s: &mut Scanner) {
        while let Some(c) = s.peek() {
            match c {
                '[' | ']' | '{' | '}' | ',' | ' ' => s.emit(1, Class::Plain),
                '#' => {
                    s.emit_rest(Class::Comment);
                    return;
                }
                '"' | '\'' => self.quoted(s, c),
                _ => {
                    let start = s.pos;
                    let mut i = start;
                    while i < s.chars.len() && !",]}".contains(s.chars[i]) {
                        if s.chars[i] == ':' && s.chars.get(i + 1) == Some(&' ') {
                            break;
                        }
                        i += 1;
                    }
                    let item: String = s.chars[start..i].iter().collect();
                    let trimmed = item.trim_end();
                    let n = trimmed.chars().count();
                    if s.chars.get(i) == Some(&':') {
                        s.emit(n, Class::Variable);
                        s.emit(i - start - n, Class::Plain);
                        s.emit(1, Class::Plain);
                        continue;
                    }
                    let class = if is_number(trimmed) || CONSTANTS.contains(&trimmed) {
                        Class::Number
                    } else {
                        Class::String
                    };
                    s.emit(n, class);
                    s.emit(i - start - n, Class::Plain);
                }
            }
        }
    }
}
