//! Highlighting of Java source files.

use super::scanner::{is_ident_char, is_ident_start, Class, Scanner};

const KEYWORDS: &[&str] = &[
    "abstract", "assert", "break", "case", "catch", "class", "continue", "default", "do", "else",
    "enum", "extends", "final", "finally", "for", "if", "implements", "import", "interface",
    "native", "new", "package", "private", "protected", "public", "return", "static", "strictfp",
    "super_", "switch", "synchronized", "throw", "throws", "transient", "try", "volatile",
    "while", "var",
];

const PRIMITIVES: &[&str] = &["boolean", "byte", "char", "double", "float", "int", "long", "short", "void"];

const CONSTANTS: &[&str] = &["true", "false", "null"];

#[derive(Default)]
pub struct JavaHighlighter {
    comment: bool,
    javadoc: bool,
    /// Brace depth of the outermost class body.
    class_depth: usize,
    brace_depth: usize,
    /// Inside of a class header (between `class` and `{`).
    class_header: bool,
    expect_class_name: bool,
    /// After `extends` or `implements`.
    inherited: bool,
    params_depth: usize,
    paren_depth: usize,
    catch_params: bool,
}

fn is_operator(c: char) -> bool {
    "=+-*/%<>!&|^~?:".contains(c)
}

impl JavaHighlighter {
    fn in_class(&self) -> bool {
        self.class_depth > 0 || self.class_header
    }

    fn plain(&self) -> Class {
        if self.in_class() {
            Class::Embedded
        } else {
            Class::Plain
        }
    }

    pub fn highlight_line(&mut self, line: &str) -> Vec<(Class, String)> {
        let mut s = Scanner::new(line);
        let trimmed = line.trim_start();
        if !self.comment && !self.in_class() && (trimmed.starts_with("import ") || trimmed.starts_with("package ")) {
            self.import_line(&mut s);
            return s.out;
        }
        while !s.eof() {
            if self.comment {
                if s.starts_with("*/") {
                    s.emit(2, Class::Comment);
                    self.comment = false;
                    self.javadoc = false;
                } else if self.javadoc && s.peek() == Some('@') && s.prev().is_some_and(|c| c.is_whitespace()) {
                    let n = 1 + s.chars[s.pos + 1..].iter().take_while(|c| c.is_alphanumeric()).count();
                    s.emit(n, Class::Keyword);
                } else {
                    s.emit(1, Class::Comment);
                }
                continue;
            }
            self.token(&mut s);
        }
        s.out
    }

    fn import_line(&mut self, s: &mut Scanner) {
        while s.peek().is_some_and(|c| c.is_whitespace()) {
            s.emit(1, Class::Plain);
        }
        let package = s.starts_with("package");
        let n = s.ident_len();
        s.emit(n, Class::Keyword);
        let mut is_static = false;
        while !s.eof() {
            let c = s.peek().unwrap();
            if c.is_whitespace() {
                s.emit(1, Class::Plain);
                continue;
            }
            if s.starts_with("static") && s.peek_at(6) == Some(' ') {
                s.emit(6, Class::Keyword);
                is_static = true;
                continue;
            }
            if is_ident_start(c) {
                // qualified name
                let start = s.pos;
                let mut i = start;
                while i < s.chars.len() && (is_ident_char(s.chars[i]) || (s.chars[i] == '.' && s.chars.get(i + 1).is_some_and(|c| is_ident_start(*c)))) {
                    i += 1;
                }
                let class = if package {
                    Class::Plain
                } else if is_static {
                    Class::Support
                } else {
                    Class::Type
                };
                s.emit(i - start, class);
                continue;
            }
            s.emit(1, Class::Plain);
        }
    }

    fn token(&mut self, s: &mut Scanner) {
        let c = s.peek().unwrap();
        let plain = self.plain();
        if c.is_whitespace() {
            s.emit(1, plain);
            return;
        }
        if s.starts_with("//") {
            s.emit_rest(Class::Comment);
            return;
        }
        if s.starts_with("/*") {
            self.javadoc = s.starts_with("/**");
            s.emit(2, Class::Comment);
            self.comment = true;
            return;
        }
        if c == '"' || c == '\'' {
            s.emit(1, Class::Plain);
            while let Some(d) = s.peek() {
                if d == c {
                    break;
                }
                if d == '\\' {
                    s.emit(2, Class::Escape);
                    continue;
                }
                s.emit(1, Class::String);
            }
            s.emit(1, Class::Plain);
            return;
        }
        if c.is_ascii_digit() && (s.pos == 0 || !is_ident_char(s.prev().unwrap())) {
            let mut i = 0;
            let hex = s.starts_with("0x") || s.starts_with("0X");
            if hex {
                i = 2;
            }
            while s.peek_at(i).is_some_and(|c| c.is_ascii_digit() || c == '_' || c == '.' || (hex && c.is_ascii_hexdigit()) || ((c == 'e' || c == 'E') && !hex)) {
                i += 1;
            }
            s.emit(i, Class::Number);
            if s.peek().is_some_and(|c| "lLfFdD".contains(c)) && !s.peek_at(1).is_some_and(is_ident_char) {
                s.emit(1, Class::Keyword);
            }
            return;
        }
        if c == '@' && s.peek_at(1).is_some_and(is_ident_start) {
            s.emit(1, plain);
            let n = s.ident_len();
            s.emit(n, Class::Variable);
            return;
        }
        if is_ident_start(c) {
            self.identifier(s);
            return;
        }
        match c {
            '{' => {
                self.brace_depth += 1;
                if self.class_header {
                    self.class_header = false;
                    self.inherited = false;
                    if self.class_depth == 0 {
                        self.class_depth = self.brace_depth;
                    }
                }
            }
            '}' => {
                if self.class_depth == self.brace_depth {
                    self.class_depth = 0;
                    s.emit(1, Class::Embedded);
                    self.brace_depth = self.brace_depth.saturating_sub(1);
                    return;
                }
                self.brace_depth = self.brace_depth.saturating_sub(1);
            }
            '(' => self.paren_depth += 1,
            ')' => {
                if self.params_depth == self.paren_depth {
                    self.params_depth = 0;
                    self.catch_params = false;
                }
                self.paren_depth = self.paren_depth.saturating_sub(1);
            }
            '[' if s.peek_at(1) == Some(']') => {
                s.emit(2, Class::Keyword);
                return;
            }
            _ => {}
        }
        if is_operator(c) && self.in_class() && !(c == '<' || c == '>') || (is_operator(c) && !self.in_class()) {
            s.emit(1, Class::Plain);
            return;
        }
        if (c == '<' || c == '>') && self.in_class() {
            // comparison operators are highlighted, generic brackets are not
            let generic = c == '<' && s.prev().is_some_and(is_ident_char)
                && s.peek_at(1).is_some_and(|d| d.is_uppercase() || d == '>')
                || c == '>' && (s.prev().is_some_and(|d| is_ident_char(d) || d == '>' || d == '<') && !s.prev().is_some_and(|d| d == ' '));
            s.emit(1, if generic { Class::Embedded } else { Class::Plain });
            return;
        }
        s.emit(1, plain);
    }

    fn identifier(&mut self, s: &mut Scanner) {
        let start = s.pos;
        let len = s.ident_len();
        let word = s.word_at(start, len);
        let after = start + len;
        let next = s.next_non_ws(after).map(|(_, c)| c);
        let plain = self.plain();
        let member = start > 0 && s.chars[start - 1] == '.';

        if self.expect_class_name {
            self.expect_class_name = false;
            s.emit(len, Class::Type);
            return;
        }
        if self.class_header && (word == "extends" || word == "implements") {
            self.inherited = true;
            s.emit(len, Class::Keyword);
            return;
        }
        if self.class_header && self.inherited {
            let generic_arg = start > 0 && s.chars[..start].iter().rev().take_while(|c| **c != ',' && **c != ' ').any(|c| *c == '<');
            s.emit(len, if generic_arg { Class::Type } else { Class::String });
            return;
        }
        if word == "instanceof" {
            s.emit(len, Class::Plain);
            return;
        }
        if KEYWORDS.contains(&word.as_str()) {
            match word.as_str() {
                "class" | "interface" | "enum" => {
                    self.expect_class_name = true;
                    self.class_header = true;
                }
                "catch" => self.catch_params = true,
                _ => {}
            }
            s.emit(len, Class::Keyword);
            if self.catch_params && word == "catch" {
                // parameters of the catch clause
                self.params_depth = self.paren_depth + 1;
            }
            return;
        }
        if PRIMITIVES.contains(&word.as_str()) {
            s.emit(len, Class::Keyword);
            return;
        }
        if CONSTANTS.contains(&word.as_str()) {
            s.emit(len, Class::Number);
            return;
        }
        if word == "this" || word == "super" {
            s.emit(len, Class::Variable);
            return;
        }
        if self.params_depth > 0 && self.paren_depth >= self.params_depth {
            if matches!(next, Some(',') | Some(')')) {
                s.emit(len, Class::Variable);
                return;
            }
            if word.chars().next().is_some_and(|c| c.is_uppercase()) {
                s.emit(len, Class::Type);
                return;
            }
            s.emit(len, plain);
            return;
        }
        if next == Some('(') && !member {
            // method or constructor declaration when preceded by a type or modifier
            let prev = s.prev_non_ws(start).map(|(_, c)| c);
            let declaration = self.in_class()
                && prev.is_some_and(|c| is_ident_char(c) || c == '>' || c == ']')
                && !matches!(self.previous_word(s, start).as_str(), "new" | "return" | "throw" | "else");
            let constructor = self.in_class() && word.chars().next().is_some_and(|c| c.is_uppercase()) && !matches!(self.previous_word(s, start).as_str(), "new");
            if declaration || constructor {
                s.emit(len, Class::Function);
                self.params_depth = self.paren_depth + 1;
                return;
            }
            if word.chars().next().is_some_and(|c| c.is_uppercase()) {
                s.emit(len, Class::Type);
                return;
            }
            s.emit(len, Class::Function);
            return;
        }
        if next == Some('(') && member {
            s.emit(len, Class::Function);
            return;
        }
        if word.chars().next().is_some_and(|c| c.is_uppercase())
            && !word.chars().all(|c| c.is_uppercase() || c.is_ascii_digit() || c == '_')
        {
            s.emit(len, Class::Type);
            return;
        }
        s.emit(len, plain);
    }

    fn previous_word(&self, s: &Scanner, start: usize) -> String {
        let mut i = start;
        while i > 0 && s.chars[i - 1].is_whitespace() {
            i -= 1;
        }
        let end = i;
        while i > 0 && is_ident_char(s.chars[i - 1]) {
            i -= 1;
        }
        s.chars[i..end].iter().collect()
    }
}
