    "s", "ms", "deg", "rad", "grad", "turn", "fr", "dpi", "dpcm", "dppx", "hz", "khz",
];

impl CssHighlighter {
    pub fn highlight_line(&mut self, line: &str) -> Vec<(Class, String)> {
        let mut s = Scanner::new(line);
        self.run(&mut s, None);
        s.out
    }

    /// Highlight until the end of the line or until `stop` is found outside
    /// of a declaration block. Returns true when stopped.
    pub fn run(&mut self, s: &mut Scanner, stop: Option<&str>) -> bool {
        while !s.eof() {
            if self.comment {
                if s.starts_with("*/") {
                    s.emit(2, Class::Comment);
                    self.comment = false;
                } else {
                    s.emit(1, Class::Comment);
                }
                continue;
            }
            if let Some(stop) = stop {
                if s.starts_with(stop) {
                    return true;
                }
