                s.emit(2, Class::Comment);
                self.comment = true;
                continue;
            }
            if self.block > 0 {
                self.declaration_token(s);
            } else if self.at_rule {
                self.at_rule_token(s);
            } else {
                self.selector_token(s);
            }
        }
        false
    }

    fn string(&mut self, s: &mut Scanner, q: char) {
        s.emit(1, Class::Plain);
        while let Some(c) = s.peek() {
            if c == q {
                s.emit(1, Class::Plain);
                return;
            }
            if c == '\\' {
                s.emit(2, Class::Escape);
                continue;
            }
            s.emit(1, Class::String);
        }
    }

