            match self.state {
                State::Comment => {
                    if s.starts_with("-->") {
                        s.emit(3, Class::Comment);
                        self.state = State::Text;
                    } else {
                        s.emit(1, Class::Comment);
                    }
                }
                State::Text => self.text(&mut s),
                State::Tag => self.tag(&mut s),
                State::Script => {
                    let rest: String = s.chars[s.pos..].iter().collect();
                    if let Some(i) = rest.to_ascii_lowercase().find("</script") {
                        let part: String = rest.chars().take(i).collect();
                        if !part.is_empty() {
                            for (class, text) in self.js.highlight_line(&part) {
                                s.push(class, &text);
                            }
                        }
                        s.pos += part.chars().count();
                        self.state = State::Text;
                    } else {
                        for (class, text) in self.js.highlight_line(&rest) {
                            s.push(class, &text);
                        }
                        s.pos = s.chars.len();
                    }
                }
                State::Style => {
                    let mut sub = Scanner::new("");
                    sub.chars = s.chars[s.pos..].to_vec();
                    let stopped = self.css.run(&mut sub, Some("</"));
                    let consumed = sub.pos;
                    for (class, text) in sub.out {
                        s.push(class, &text);
                    }
                    s.pos += consumed;
                    if stopped {
                        self.state = State::Text;
                    }
                }
            }
        }
        s.out
    }

    fn text(&mut self, s: &mut Scanner) {
        let c = s.peek().unwrap();
        if s.starts_with("<!--") {
            s.emit(4, Class::Comment);
            self.state = State::Comment;
            return;
        }
        if c == '<' {
            let closing = s.peek_at(1) == Some('/');
            let bang = s.peek_at(1) == Some('!');
            let start = if closing || bang { 2 } else { 1 };
            let n = s.chars[s.pos + start..]
                .iter()
                .take_while(|c| is_ident_char(**c) || **c == '-' || **c == ':')
                .count();
            if n == 0 {
                s.emit(1, Class::Plain);
                return;
            }
            let name: String = s.chars[s.pos + start..s.pos + start + n].iter().collect();
            s.emit(start, Class::Plain);
            s.emit(n, Class::Variable);
            self.state = State::Tag;
            self.pending = None;
            if !closing {
                match name.to_ascii_lowercase().as_str() {
                    "script" => self.pending = Some(State::Script),
                    "style" => self.pending = Some(State::Style),
                    _ => {}
                }
            }
            return;
        }
        if c == '&' {
            let n = s.chars[s.pos + 1..].iter().take_while(|c| c.is_alphanumeric() || **c == '#').count();
            if n > 0 && s.peek_at(n + 1) == Some(';') {
                s.emit(1, Class::Function);
                s.emit(n, Class::Number);
                s.emit(1, Class::Function);
                return;
            }
        }
        s.emit(1, Class::Plain);
    }

    fn tag(&mut self, s: &mut Scanner) {
        let c = s.peek().unwrap();
        if c == '>' || s.starts_with("/>") {
            let n = if c == '>' { 1 } else { 2 };
            s.emit(n, Class::Plain);
            self.state = State::Text;
            if n == 1 {
                if let Some(state) = self.pending.take() {
                    self.state = state;
                    if state == State::Style {
                        self.css = CssHighlighter::default();
                    }
                }
            }
            return;
        }
        if c == '"' || c == '\'' {
            s.emit(1, Class::Plain);
            while let Some(d) = s.peek() {
                if d == c {
                    break;
                }
                s.emit(1, Class::String);
            }
            s.emit(1, Class::Plain);
            return;
        }
        if c == '=' {
            s.emit(1, Class::Plain);
            // unquoted values
            if s.peek().is_some_and(|d| !d.is_whitespace() && d != '"' && d != '\'' && d != '>') {
                let n = s.chars[s.pos..].iter().take_while(|d| !d.is_whitespace() && **d != '>').count();
                s.emit(n, Class::String);
            }
            return;
        }
        if c.is_alphabetic() {
            let n = s.chars[s.pos..].iter().take_while(|c| is_ident_char(**c) || **c == '-' || **c == ':').count();
            let name: String = s.chars[s.pos..s.pos + n].iter().collect();
            let class = if name.eq_ignore_ascii_case("id") { Class::Function } else { Class::Number };
            s.emit(n, class);
            return;
        }
        s.emit(1, Class::Plain);
    }
}
