{"command":"cd /workspace && cat > src/ui/context_viewer.rs <<'EOF'
//! Context viewer.
//!
//! The context viewer displays the content of the file containing the
//! selected match. It can be placed either on the right side of the result
//! list (vertical split) or below it (horizontal split). Its size is a
//! percentage of the main area which can be adjusted at runtime.
//!
//! The content of the file is read when a match from a different file is
//! selected and the syntax highlighted lines are cached until another file
//! is selected. The line containing the selected match is highlighted using
//! the background color of the current theme.
//!
//! The first displayed line is computed from the line number of the selected
//! match and from the height of the viewer:
//!
//! ```text
//! first line = line number - (height / 2 + 1)
//! ```
//!
//! Lines past the end of the file are left empty and long lines are
//! truncated at the right border of the viewer.

use ratatui::{
    layout::{Constraint, Direction, Layout, Rect},
    style::Style,
    text::{Line, Span},
    widgets::{Block, BorderType},
    Frame,
};

use crate::args::{ContextViewerPosition, ThemeKind};
use crate::ui::highlight;
use crate::ui::theme::Theme;

/// Smallest size of the context viewer, in percent of the main area.
const MIN_SIZE: u16 = 20;
/// Largest size of the context viewer, in percent of the main area.
const MAX_SIZE: u16 = 80;
/// Change of the size when the viewer is enlarged or shrunk.
const SIZE_STEP: u16 = 5;
/// Initial size of the viewer.
const DEFAULT_SIZE: u16 = 50;

/// A line of the file split into styled segments.
type HighlightedLine = Vec<(Style, String)>;

pub struct ContextViewer {
    /// Position of the viewer relative to the result list.
    position: ContextViewerPosition,
    /// Size of the viewer in percent.
    size: u16,
    /// Path of the file whose content is cached.
    file_path: Option<String>,
    /// Highlighted content of the cached file.
    highlighted: Vec<HighlightedLine>,
}

impl ContextViewer {
    /// Create a viewer displayed at the given position.
    pub fn new(position: ContextViewerPosition) -> Self {
        Self {
            position,
            size: DEFAULT_SIZE,
            file_path: None,
            highlighted: vec![],
        }
    }

    /// Show the viewer on the right side of the list, or hide it when it
    /// is already displayed there.
    pub fn toggle_vertical(&mut self) {
        self.position = if self.position == ContextViewerPosition::Vertical {
            ContextViewerPosition::None
        } else {
            ContextViewerPosition::Vertical
        };
    }

    /// Show the viewer below the list, or hide it when it is already
    /// displayed there.
    pub fn toggle_horizontal(&mut self) {
        self.position = if self.position == ContextViewerPosition::Horizontal {
            ContextViewerPosition::None
        } else {
            ContextViewerPosition::Horizontal
        };
    }

    /// Enlarge the viewer. The size is changed even when the viewer is
    /// hidden.
    pub fn increase_size(&mut self) {
        self.size = std::cmp::min(self.size + SIZE_STEP, MAX_SIZE);
    }

    /// Shrink the viewer. The size is changed even when the viewer is
    /// hidden.
    pub fn decrease_size(&mut self) {
        self.size = std::cmp::max(self.size - SIZE_STEP, MIN_SIZE);
    }

    /// Split the main area into the result list area and the viewer area.
    pub fn split(&self, area: Rect) -> (Rect, Option<Rect>) {
        let direction = match self.position {
            ContextViewerPosition::None => return (area, None),
            ContextViewerPosition::Vertical => Direction::Horizontal,
            ContextViewerPosition::Horizontal => Direction::Vertical,
        };
        let chunks = Layout::default()
            .direction(direction)
            .constraints([
                Constraint::Percentage(100 - self.size),
                Constraint::Percentage(self.size),
            ])
            .split(area);
        (chunks[0], Some(chunks[1]))
    }

    /// Read and highlight the file at `path` unless it is already cached.
    fn update_file(&mut self, path: &str, theme_kind: ThemeKind) {
        if self.file_path.as_deref() == Some(path) {
            return;
        }
        self.file_path = Some(path.to_string());
        let content = std::fs::read(path).unwrap_or_default();
        let content = String::from_utf8_lossy(&content);
        self.highlighted = highlight::highlight(path, &content, theme_kind);
    }

    /// Index of the first displayed line (0 based).
    fn first_line_index(line_number: u64, height: u16) -> usize {
        let first_line = line_number.saturating_sub(height as u64 / 2 + 1).max(1);
        (first_line - 1) as usize
    }

    /// Build the line displayed for the given index of the file.
    fn line(&self, index: usize, selected: bool, theme: &Theme) -> Option<Line<'static>> {
        let spans = self.highlighted.get(index)?;
        let line = Line::from(
            spans
                .iter()
                .map(|(style, text)| Span::styled(text.clone(), *style))
                .collect::<Vec<_>>(),
        );
        if selected {
            Some(line.style(Style::default().bg(theme.highlight_color())))
        } else {
            Some(line)
        }
    }

    /// Area of a single row of the viewer.
    fn row_area(inner: Rect, row: u16) -> Rect {
        Rect {
            x: inner.x,
            y: inner.y + row,
            width: inner.width,
            height: 1,
        }
    }

    /// Draw the viewer for the selected match.
    ///
    /// The block is always drawn, the content only when a match is
    /// selected.
    pub fn draw(
        &mut self,
        frame: &mut Frame,
        area: Rect,
        selected: Option<(String, u64)>,
        theme: &Theme,
    ) {
        let block = Block::bordered().border_type(BorderType::Rounded);
        let inner = block.inner(area);
        frame.render_widget(block, area);
        let (path, line_number) = match selected {
            Some(s) => s,
            None => return,
        };
        self.update_file(&path, theme.kind);
        self.draw_lines(frame, area, inner, line_number, theme);
    }

    /// Draw the lines of the file around the selected line.
    fn draw_lines(
        &self,
        frame: &mut Frame,
        area: Rect,
        inner: Rect,
        line_number: u64,
        theme: &Theme,
    ) {
        let rows: Vec<Rect> = area.rows().collect();
        let viewer_top_row_rectangle = rows[0];
        let _ = viewer_top_row_rectangle;
        let first = Self::first_line_index(line_number, inner.height);
        for row in 0..inner.height {
            let index = first + row as usize;
            let selected = index as u64 + 1 == line_number;
            let Some(line) = self.line(index, selected, theme) else {
                break;
            };
            frame.render_widget(line, Self::row_area(inner, row));
        }
    }
}
EOF
