    /// Split the main area into the result list area and the viewer area.
    pub fn split(&self, area: Rect) -> (Rect, Option<Rect>) {
        let direction = match self.position {
            ContextViewerPosition::None => return (area, None),
            ContextViewerPosition::Vertical => Direction::Horizontal,
            ContextViewerPosition::Horizontal => Direction::Vertical,
        };
        let chunks = Layout::default()
            .direction(direction)
            .constraints([
                Constraint::Percentage(100 - self.size),
                Constraint::Percentage(self.size),
            ])
            .split(area);
        (chunks[0], Some(chunks[1]))
    }

    /// Read and highlight the file at `path` unless it is already cached.
    fn update_file(&mut self, path: &str, theme_kind: ThemeKind) {
        if self.file_path.as_deref() == Some(path) {
            return;
        }
        self.file_path = Some(path.to_string());
        let content = std::fs::read(path).unwrap_or_default();
        let content = String::from_utf8_lossy(&content);
        self.highlighted = highlight::highlight(path, &content, theme_kind);
    }

    /// Index of the first displayed line (0 based).
    fn first_line_index(line_number: u64, height: u16) -> usize {
        let first_line = line_number.saturating_sub(height as u64 / 2 + 1).max(1);
        (first_line - 1) as usize
    }

    /// Build the line displayed for the given index of the file.
    fn line(&self, index: usize, selected: bool, theme: &Theme) -> Option<Line<'static>> {
        let spans = self.highlighted.get(index)?;
        let line = Line::from(
            spans
                .iter()
                .map(|(style, text)| Span::styled(text.clone(), *style))
                .collect::<Vec<_>>(),
        );
        if selected {
            Some(line.style(Style::default().bg(theme.highlight_color())))
        } else {
            Some(line)
        }
    }

    /// Area of a single row of the viewer.
    fn row_area(inner: Rect, row: u16) -> Rect {
        Rect {
            x: inner.x,
            y: inner.y + row,
            width: inner.width,
            height: 1,
        }
    }

    /// Draw the viewer for the selected match.
    ///
    /// The block is always drawn, the content only when a match is
    /// selected.
    pub fn draw(
        &mut self,
        frame: &mut Frame,
        area: Rect,
        selected: Option<(String, u64)>,
        theme: &Theme,
    ) {
        let block = Block::bordered().border_type(BorderType::Rounded);
        let inner = block.inner(area);
        frame.render_widget(block, area);
        let (path, line_number) = match selected {
            Some(s) => s,
            None => return,
        };
        self.update_file(&path, theme.kind);
        self.draw_lines(frame, area, inner, line_number, theme);
    }

    /// Draw the lines of the file around the selected line.
    fn draw_lines(
        &self,
        frame: &mut Frame,
        area: Rect,
        inner: Rect,
        line_number: u64,
        theme: &Theme,
    ) {
        let rows: Vec<Rect> = area.rows().collect();
        let viewer_top_row_rectangle = rows[0];
        let _ = viewer_top_row_rectangle;
        let first = Self::first_line_index(line_number, inner.height);
        for row in 0..inner.height {
            let index = first + row as usize;
            let selected = index as u64 + 1 == line_number;
            let Some(line) = self.line(index, selected, theme) else {
                break;
            };
            frame.render_widget(line, Self::row_area(inner, row));
        }
    }
}
